-- ════════════════════════════════════════════════════════════
-- 2. Bảng câu ví dụ
-- ════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS mnn_sentences (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site_id      uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
  lesson_id    uuid NOT NULL REFERENCES mnn_lessons(id) ON DELETE CASCADE,
  grammar_id   uuid REFERENCES mnn_grammar(id) ON DELETE CASCADE,
  ja_kanji     text NOT NULL,
  ja_kana      text NOT NULL,
  vi           text NOT NULL,
  has_furigana boolean NOT NULL DEFAULT false,
  source       text,
  order_index  integer DEFAULT 0,
  created_at   timestamptz DEFAULT now()
);

-- Kéo mnn_sentences về đúng schema hiện tại. Bảng mới thì đây là no-op.
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS lesson_id uuid;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS grammar_id uuid;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS ja_kanji text;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS ja_kana text;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS vi text;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS has_furigana boolean;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS source text;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS order_index integer DEFAULT 0;
ALTER TABLE mnn_sentences ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();

CREATE INDEX IF NOT EXISTS mnn_sentences_lesson_idx
  ON mnn_sentences (site_id, lesson_id, order_index);
CREATE INDEX IF NOT EXISTS mnn_sentences_grammar_idx
  ON mnn_sentences (grammar_id);

ALTER TABLE mnn_sentences ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "public read mnn_sentences" ON mnn_sentences;
CREATE POLICY "public read mnn_sentences" ON mnn_sentences FOR SELECT USING (true);

-- ════════════════════════════════════════════════════════════
-- 3. Xoá ngữ pháp cũ. Câu xoá trước vì nó trỏ vào ngữ pháp.
-- ════════════════════════════════════════════════════════════
DELETE FROM mnn_sentences WHERE site_id = '1219bda2-aa1e-4288-ab7e-caff011cdf5c';
DELETE FROM mnn_grammar WHERE lesson_id IN (
  SELECT id FROM mnn_lessons WHERE site_id = '1219bda2-aa1e-4288-ab7e-caff011cdf5c');

-- ════════════════════════════════════════════════════════════
-- 4. Ngữ pháp — 252 mẫu
--    Ghép với mnn_lessons theo lesson_number, không cần biết uuid.
-- ════════════════════════════════════════════════════════════
INSERT INTO mnn_grammar
  (site_id, lesson_id, pattern, explanation_vi, example_ja, example_vi, order_index)
SELECT '1219bda2-aa1e-4288-ab7e-caff011cdf5c', l.id, v.pattern, v.explanation_vi,
       v.example_ja, v.example_vi, v.ord
FROM (VALUES
  (1, 'Trợ từ trong tiếng Nhật : は、も、の、か、.', 'Khác với tiếng Viêt, tiếng Nhật là thứ ngôn ngữ chắp dính. Các từ hoặc ngữ có thể tách rời và được nối với nhau bởi những trợ từ. Có nhiều loại trợ từ và cách sử dụng của chúng rất đa dạng. Chính nhờ các trợ từ này mà thứ tự của các thành phần trong một câu của tiếng Nhật có thể được thay đổi dễ dàng mà không làm thay đổi ngữ nghĩa của câu. Trong bài 1, chúng ta sẽ gặp 4 trợ từ là は、も、の、か …', NULL, NULL, 1),
  (1, 'N1 は N2 です N1 là N2.', 'Trợ từ は được dùng sau N1 để biểu thị N1 là chủ đề của câu. です được dùng ở cuối câu khẳng định thì hiện tại dạng “ N1 là N2” và thể hiện sự tôn trọng, lịch sự đối với người nghe.', NULL, NULL, 2),
  (1, 'N1 は N2 じゃ ありません', 'じゃ ありません là dạng phủ định của です .Đây là cách nói được sử dụng trong giao tiếp hội thoại hàng ngày. Khi viết, người ta sử dụng dạng chính thống của nó là では ありません.', '私はぎんこういんじゃ（では）ありません。', 'Tôi không phải là nhân viên ngân hàng.', 3),
  (1, '～も～です==> ~ cũng là ~', 'も được sử dụng với tiền đề là khi sự việc mà nó chỉ ra giống với sự việc ở mệnh đề trước.', '私はベトナム人です。', 'Tôi là người Việt Nam', 4),
  (1, 'N1 の N2 です。S は ～さいです ==> S ~ tuổi', 'Nối 2 danh từ lại với nhau, danh từ trước xác định cho danh từ sau Trong trường hợp này biểu hiện tính sở thuộc, tức là N2 là một bộ phận của N1, thuộc về N1.', '私はなごやだいがくの学生です。', 'Tôi là sinh viên trường đại học Nagoya', 5),
  (2, 'これ/ それ/ あれ', 'これ、それ、あれ là những từ chỉ vật và có chức năng như 1 danh từ. これ được dùng để chỉ những vật ở gần người nói それ được dùng để chỉ những vật ở gần người nghe あれ được dùng để chỉ những vật ở cách xa cả người nói và người nghe.', 'これはじしょですか。', 'Đây là quyển từ điển phải không?', 1),
  (2, 'このN/ そのN/ あのN', 'この」、「その」、「あの」 là những từ dùng để bổ nghĩa cho danh từ đứng đằng sau nó. Tương tự như これ、それ、あれ , ta có : この dùng để bổ nghĩa cho những danh từ chỉ những vật ở gần người nói. その dùng để bổ nghĩa cho những danh từ chỉ những vật ở gần người. あの dùng để bổ nghĩa cho những danh từ chỉ những vật ở xa cả người nói và người nghe.', 'このほんは何のほんですか。', 'Quyển sách này là sách gì ?', 2),
  (2, 'そうです/ そうじゃ ありません', '「 そう」 được sử dụng để trả lời vắn tắt cho một câu nghi vấn danh từ ( câu nghi vấn mà tận cùng bằng những danh từ). 「はい、そうです」 là câu trả lời khẳng định và 「いいえ、そうじゃ ありません」 là câu trả lời phủ định. Trong câu trả lời, ta nên tránh lặp lại những từ giống với câu hỏi mà nên sử dụng 「そう」 để trả lời sẽ tự nhiên hơn. Lưu ý : Chỉ được sử dụng 「そう」 để trả lời khi câu nghi vấn có tận cùng là danh từ . Với câu nghi vấn tận cùng là động từ hoặc tính từ ( sẽ học trong các bài 4 ) thì không được sử dụng cách trả lời này.', 'それはテレホンカードですか。', 'Đây là thẻ điện thoại phải không?', 3),
  (2, '～は S1 ですか 、S2 ですか', 'Dạng câu 「 S1 ですか、 S2 ですか」 là dạng câu hỏi lựa chọn, trong đó người hỏi đưa ra 2 phương án trả lời để người nghe chọn 1 phương án đúng. Khi trả lời cho dạng câu hỏi này, ta không sử dụng các từ 「はい」 hoặc 「いいえ」 mà chỉ cần nói ra phương án mình lựa chọn.', 'これはポールペンですか、シャープペンシルですか。', 'Đây là bút bi hay bút chì máy ?', 4),
  (2, 'N1のN2', 'Trong bài 1 chúng ta đã học 1 ý nghĩa của trợ từ 「の」 , đó là dùng để chỉ việc N2 là một bộ phận của N1. Trong bài 2 này, chúng ta sẽ học 2 ý nghĩa khác của trợ từ này. N1 dùng để giải thích, bổ nghĩa cho N2:', 'これはコンピューターのほんです。', 'Đây là sách về máy tính.', 5),
  (2, 'そうですか', 'Dùng khi người nói nhận được một thông tin gì đó mới (và muốn thế hiện họ đã hiểu thông tin đó.) Khi nói, chữ か ở cuối câu phải hạ thấp giọng xuống.', 'このかさはあなたのですか。', 'Đây là ô của bạn phải không?', 6),
  (3, 'ここ/そこ/あそこ/こちら/そちら/あちら', 'Bài 2, chúng ta đã học những danh từ chỉ vật như これ、それ、あれ .Trong bài này, chúng ta sẽ học về những danh từ chỉ nơi chốn là ここ、そこ、あそこ . ここ dùng để chỉ chỗ mà người nói đứng. Nó cũng được dùng để chỉ nơi mà người nói và người nghe cùng đứng. そこ dùng để chỉ chỗ mà người nghe đứng hoặc một địa điểm cách cả người nói và người nghe 1 chút. あそこ dùng để chỉ một địa điểm ở cách xa cả người nói và người nghe. a) こちら、そちら、あちら là những danh từ chỉ phương hướng. Ngoài ra, những từ này cũng được dùng để chỉ địa điểm, và trong trường hợp này thì nó biểu hiện sự lịch sự, lễ phép hơn các từ ここ、そこ、あそこ .', 'ここはきょうしつです。', 'Đây là phòng học.', 1),
  (3, 'N1は N2（địa điểm）です', 'Mẫu này dùng để diễn tả về vị trí của một địa điểm, một vật hoặc một người nào đó.', 'おてあらいはあそこです。', 'Nhà vệ sinh ở kia.', 2),
  (3, 'どこ/どちら', 'a, どこ có nghĩ là “ ở đâu”, còn どちら có nghĩa là ở hướng nào, ở đằng nào. どちら cũng có thể được dùng với nghĩa là “ ở đâu” , và trong trường hợp này thì nó có sắc thái lịch sự hơn, lễ phép hơn là どこ .', 'わたしのうちはハノイです。Bさんのうちはどこですか。', 'Nhà tôi ở Hà Nội. Nhà anh B ở đâu?', 3),
  (3, 'N1のN2', 'Khi N1 là tên nước/ tên địa phương/tên công ty và N2 là một sản phẩm, thì mẫu này có nghĩa là N2 được sản xuất tại nước đó/ tại địa phương đó/bởi công ty đó. Trong mẫu này thì từ để hỏi どこ được dùng để hỏi nơi/ công ty đã sản xuất ra sản phẩm N2.', 'これはトヨタのじどうしゃです。', 'Đây là xe hơi của công ty Toyota.', 4),
  (3, '～は いくらですか ―＞ ～は～円です。', 'Mẫu này được dùng để hỏi và trả lời về giá tiền của một đồ vật nào đó.', 'このネクタイは１５００円です。', 'Cái cà vạt này giá 1500 yên.', 5),
  (3, 'こ/そ/あ/ど', 'Vật', 'これそれあれどれ', 'Người,vật', 6),
  (4, '今(いま) ～時(じ) ～分(ふん)です', 'Trong tiếng Nhật, người ta sử dụng các đơn vị đếm thời gian là 時 じ （ giờ ） và 分 ふん （ phút ） kết hợp với các số đếm để nói về thời gian. Các số đếm sẽ được đặt trước các đơn vị chỉ thời gian.', '今何時ですか。', 'Bây giờ là mấy giờ ?', 1),
  (4, 'Vます', 'Thể ます là một trong những thể của động từ trong tiếng Nhật. Những động từ kết thúc bằng ます có chức năng làm vị ngữ của câu. Thể ます làm cho câu nghe lịch sự hơn.', 'わたしはまいにちべんきょうします。', 'Tôi học mỗi ngày.', 2),
  (4, 'Vます/Vません/Vました/Vませんでした', 'Thể ます được dùng để diễn tả một sự thật khách quan ( VD: nước sôi ở 100 độ, mặt trời mọc từ đằng Đông,..) hoặc một việc đã trở thành thói quen. Có thể gọi ます là thể khẳng định của động từ ở thời không quá khứ ( tức là bao gồm cả hiện tại và tương lai) dạng lịch sự. Thể phủ định và thể quá khứ của ます được biến đổi như bảng dưới đây Không quá khứ (hiện tại/tương lai) Quá khứ Khẳng định', '(おき)ます(おき）ました', 'Phủ định', 3),
  (4, 'N (thời gian) に V', 'Để chỉ thời điểm tiến hành một động tác, một sự di chuyển, ta thêm trợ từ に ở sau danh từ chỉ thời gian. Tuy nhiên, cần lưu ý là chỉ được thêm trợ từ に vào trước những danh từ đi cùng với số đếm ( Ví dụ: ngày, tháng, năm hoặc giờ,..). Ta cũng có thể thêm trợ từ に vào trước danh từ chỉ các ngày trong tuần mặc dù nó không thật sự cần thiết. Còn lại các danh từ chỉ thời gian không đi cùng với số đếm khác ( ví dụ : sáng nay, hôm qua, mùa hè,..) thì không thêm trợ từ に v ào đằng sau.', '６時半じはんにおきます。', 'Tôi dậy lúc 6 rưỡi.', 4),
  (4, 'N1 から N2 まで', 'から chỉ thời gian hoặc địa điểm bắt đầu một sự việc nào đó, còn まで chỉ thời gian hoặc địa điểm kết thúc một sự việc nào đó.', 'ごぜん９じからごご５じまではたらきます。', 'Tôi làm việc từ 9 giờ sáng đến 5 giờ chiều.', 5),
  (4, 'N1 と N2', 'Trợ từ と được dùng để nối 2 danh từ với nhau.', 'ぎんこうのやすみはどようびとにちようびです。', 'Ngân hàng nghỉ(đóng cửa) ngày thứ 7 và Chủ Nhật.', 6),
  (4, 'ね', 'Trong tiếng Nhật có những từ được gọi là “ từ cuối câu” ( giống như “nhỉ”, “ đấy” ,..của tiếng Việt), chúng được đặt ở cuối mỗi câu để biểu hiện thái độ của người nói. ね được dùng ở cuối câu để truyền đạt cho người nghe cảm xúc của mình hay thể hiện sự mong muốn người nghe đồng tình với nhũng gì mà mình nói ( ね không được sử dụng khi độc thoại). ね còn được sử dụng để xác nhận lại một sự việc nào đó. Khi sử dụng các “ từ cuối câu” này phải lưu ý đến ngữ điệu đọc , vì tùy vào cách lên giọng hay xuống giọng mà ý nghĩa câu sẽ khác nhau.', 'まいあさ9じから5じまでべんきょうします。', 'Hàng sáng tôi học từ 9 giờ đến 5 giờ.', 7),
  (5, 'N ( địa điểm) へ いきます/ きます/ かえります', 'Khi động từ biểu thị sự di chuyển đến một nơi nào đó, như động từ いきます、きます、かえります ,v.v.. thì người ta thêm vào sau danh từ chỉ địa điểm trợ từ へ để biểu thị phương hướng di chuyển. Lưu ý: Trong trường hợp này, trợ từ へ được đọc là “ e”', 'ホーチミンしへいきます。', 'Tôi sẽ đi thành phố Hồ Chí Minh.', 1),
  (5, '( Từ để hỏi ) + [ trợ từ ]+ [ も ]+ [ phủ định ]', 'Khi trợ từ も đứng ngay sau từ để hỏi （ VD: なん、だれ、どこ、 .. ） trong câu phủ định thì tất cả những gì trong phạm trù bị từ để hỏi nêu ra đều bị phủ nhận.', 'きのうどこ[へ]もいきませんでした。', 'H ôm qua tôi không đi đâu cả .', 2),
  (5, 'N (phương tiện giao thông ) で いきます/きます/かえります', 'Trợ từ で được dùng để chỉ phương tiện hay cách thức. Khi động từ biểu thị sự di chuyển （例：いきます、きます、かえります ,… ） được sử dụng với trợ từ で thì で chỉ phương tiện di chuyển di chuyển. Danh từ đứng trước で là một danh từ chỉ phương tiện di chuyển', '（例：バス、でんしゃ、しんかんせん,..）バスでだいがくへきます。', 'Tôi đi học bằng xe bus.', 3),
  (5, 'N (người/ con vật) と V', 'Khi bạn ( hoặc người khác) làm việc gì đó cùng với người khác ( hoặc với một con vật) thì ta thêm trợ từ と vào sau danh từ chỉ người ( con vật) đó để chỉ mối liên hệ.', 'かぞくとベトナムへきました。', 'Tôi đã tới Việt Nam cùng cả nhà ( cùng với gia đình) .', 4),
  (5, 'いつ', 'Để hỏi về thời gian ,người ta thường sử dụng từ để hỏi なん như なん じ 、なん ようび 、なん がつ なん にち . Ngoài những từ này, người ta còn dùng từ để hỏi いつ ( khi nào, bao giờ) để hỏi về thời điểm đã/ sẽ xảy ra một việc gì đó. Từ để hỏi いつ không bao giờ đi cùng với trợ từ に .', 'いつハノイへきましたか。(khôngnói:いつにハノイへきましたか)（X）', 'Bạn tới Hà Nội khi nào?', 5),
  (5, 'Sよ', 'Trợ từ cuối câu “ よ ” được đặt ở cuối câu để diễn tả về một việc mà người nghe chưa biết hoặc để biểu lộ ý kiến của mình. Phát âm mạnh chữ よ sẽ gieo cho người nghe có ấn tượng như là bị ép buộc, vì vậy nên phát âm một cách nhẹ nhàng.', 'このでんしゃはこうしえんへいきますか。', 'Chuyến tàu này đến Koshien phải không?', 6),
  (6, 'N を V', 'Trợ từ を được dùng để chỉ đối tượng trực tiếp của động từ. Động từ trong mẫu này là những động từ mà những tác động của nó gây ảnh hưởng lên một khách thể khác ( VD: làm mất đi, làm biến dạng, ...) . を có cách phát âm giống với お nhưng nó chỉ được sử dụng khi viết trợ từ.', 'わたしはジュースをのみます。', 'Tôi uống nước ngọt', 1),
  (6, 'Nをします', 'Có rất nhiều danh từ được dùng để chỉ đối tượng của động từ します。します dùng để chỉ việc một thực hiện một hành động được miêu tả bởi danh từ N.Hãy xem một vài ví dụ dưới đây: Chơi một môn thể thao hay một trò chơi nào đó', 'サッカーをします', 'Chơi bóng đá', 2),
  (6, 'なにを しますか', 'Mẫu câu trên dùng để hỏi ai đó làm gì?', 'げつようびなにをしますか。', 'Bạn làm gì vào thứ 2', 3),
  (6, 'なん và なに', 'Cả 2 từ trên đều có nghĩa là “ Cái gì” ( viết chung một chữ Hán) .Dùng なん hay なに là căn cứ vào từ đứng đằng sau nó. なん được sử dụng trong các trường hợp sau Khi nó đứng trước một từ bắt đầu bằng các chữ cái thuộc các hàng た、だ、な trong bảng chữ cái.', 'それはなんですか。なんのほんですか。なんといいますすか。', 'Khi đứng sau nó là các tiếp vĩ ngữ chỉ cách đếm ：なん さい 、なん ばん 、なん ようび 、なん じ 、 ...', 4),
  (6, 'N（ địa điểm ）で V', 'Trong bài trước chúng ta đã học trợ từ へ đi sau danh từ chỉ địa điểm và kết hợp với các động từ chỉ sự di chuyển （いきます、きます、かえります） để chỉ phương hướng, đích đến của di chuyển đó. Trong bài này, chúng ta sẽ học thêm một trợ từ nữa cùng được đặt sau danh từ chỉ địa điểm nhưng lại mang ý nghĩa khác. Trợ từ で đứng sau danh từ chỉ địa điểm và trước động từ (không phải động từ chỉ sự di chuyển) để biểu thị nơi diễn ra hành động, sự việc đó.', 'えきでしんぶんをかいます。', 'Tôi mua báo ở ga.', 5),
  (6, 'Vませんか', 'Tuy có か ở cuối câu nhưng đây không phải là một câu hỏi mà nó được sử dụng khi bạn muốn rủ ( mời) ai đó làm việc gì đó.', 'いっしょにチャン・ティエンプラザへいきませんか。', 'Chúng ta cùng đi tới Trang Tien Plaza đi .', 6),
  (6, 'Vましょう', 'Mẫu này dùng khi người nói muốn tích cực rủ người nghe làm chung một việc gì. Nó cũng được sử dụng khi tích cực đáp ứng lời mời, sự rủ rê đó.', 'ちょっとやすみましょう。', 'Chúng ta nghỉ một chút đi .', 7),
  (6, 'お～', 'Như đã học trong bài 3, tiếp đầu ngữ お được đặt trước một từ nào đó có liên quan tới người nghe hoặc người thứ 3 để thể hiện sự tôn trọng ( VD : おくに ). Ngoài ra, nó còn được đặt trước rất nhiều từ khác nữa khi người nói muốn nói một cách lịch sự ( VD : [ お ] さけ、 [ お ] はなみ ,..) Có rất nhiều từ thường được đi kèm với お nhưng không phải thể hiện sự tôn trọng hoặc lịch sự mà đơn thuần chỉ là thói quen của người Nhật ( VD: おちゃ、おかね ,..) Luyện tập Các bạn comment đáp án, các sensei tại Riki sẽ vào chữa chi tiết nha', NULL, NULL, 8),
  (7, 'Dụng cụ/ phương tiện で V', 'Trong 2 bài trước, chúng ta đã học trợ từ で với ý nghĩa để chỉ phương tiện giao thông và chỉ nơi chốn, địa điểm diễn ra hành động. Trong bài này, chúng ta học thêm một ý nghĩa nữa của trợ từ で , dùng để chỉ phương tiện, phương pháp dùng để tiến hành một hành động, động tác nào đó. Điều cần lưu ý ở đây là trợ từ で có rất nhiều cách dùng và mỗi cách dùng lại mang một chức năng, một ý nghĩa khác nhau. Trợ từ で ta học trong bài này cũng là chỉ phương tiện và phương pháp, nên nó có chức năng giống với trợ từ で khi dùng để chỉ cách thức di chuyển ( bằng phương tiện giao thông nào), chứ hoàn toàn khác với chức năng chỉ địa điểm nơi xảy ra hành động mà ta đã học trong bài 6.', 'はしでたべます。', 'Ăn bằng đũa .', 1),
  (7, '“ Từ/ câu” は ～ごで 何(なん)ですか。', 'Mẫu trên dùng để hỏi cách nói một câu/ một từ bằng thứ tiếng khác. Lưu ý : Khi nói bằng một thứ tiếng nào đó, thì ngôn ngữ đó được coi như phương tiện để ta truyền đạt, vì thế mà nó cũng đi kèm với trợ từ で ( xem ví dụ 2 ở mẫu trên).', '「ありがとう」はベトナムごでなんですか。', '“ ありがとう ” tiếng Việt là gì?', 2),
  (7, 'N( người) に あげます、かします、おしえます、かけます、..', 'Những động từ như あげます、かします、おしえます、かけます、 .. phải đi kèm với một danh từ chỉ người là đối tượng của hành động cho, cho mượn, dạy, gọi,... của chủ thể. Trợ từ に được đặt sau danh từ chỉ người để chỉ đối tượng đó. Như vậy khác với các động từ chúng ta đã học từ đầu tới gìờ thường chỉ đi kèm một trợ từ, các động từ như あげます、かします、おしえます、かけます、 ..cần phải đi kèm với 2 trợ từ là を (chỉ đối tượng của hành động- thường là đồ vật) に ( hoặc から - chỉ hướng của hành động- thường là người) . Thứ tự trong câu thường là （ ～は）～に～を', 'やまださんはきむらさんにはなをあげました。', 'Anh Yamada tặng hoa cho chị Kimura', 3),
  (7, 'N( người) に もらいます、ならいます、かります、...', 'Cũng như trong tiếng Việt, tiếng Nhật cũng có những cặp động từ tương ứng.', 'きむらさんはやまださんにはなをもらいました。', 'Chị Kimura nhận được hoa từ anh Yamada.', 4),
  (7, 'もう Vました', 'もう có nghĩa là “ rồi” và được sử dụng với động từ ở dạng V ました . Trong trường hợp này, V ました không phải có ý nghĩa là hành động xảy ra ở quá khứ mà có nghĩa là hành động đó đã kết thúc rồi. Câu trả lời cho câu hỏi もう V ました là はい、もう V ました hoặc いいえ、まだです', NULL, NULL, 5),
  (8, 'けいようし ( Tính từ )', 'Tính từ được sử dụng trong câu với chức năng làm vị ngữ của câu hoặc làm định ngữ cho danh từ đứng sau nó. Tính từ trong tiếng được chia thành 2 nhóm là : Tính từ đuôi い （いーけいようし） và tính từ đuôi （なーけいようし） . Xét về mặt cấu tạo, cả 2 loại tính từ này đều được cấu tạo từ 2 bộ phận là phần thân và phần đuôi. Ở dạng nguyên thể ( tức là dạng khẳng định không quá khứ ), phần đuôi của tính từ có 2 dạng cơ bản là い và な . Tùy thuộc vào cấu trúc ngữ pháp của câu mà đuôi của tính từ sẽ được biến đổi cho phù hợp ( phần thân vẫn giữ nguyên)', NULL, NULL, 1),
  (8, 'Nは なーけいようし（な）です Nは いーけいようし（～い）です。', 'です được đặt ở cuối một câu tính từ để thể hiện sự tôn trọng, lịch sự của người nói đối với người nghe. Khi đứng trước です trong câu tính từ thì ： tính từ đuôi い : vẫn giữ nguyên đuôi い tính từ đuôi な : bỏ đuôi なーーーー＞ Phần thân + です', 'かなむらせんせいはしんせつ（な）です。', 'Cô Kanamura thân thiện', 2),
  (8, 'Dạng nghi vấn của câu tính từ', 'Dạng nghi vấn của câu tính từ cũng được cấu tạo tương như của câu danh từ và câu động từ, nghĩa là ta sẽ thêm か vào cuối câu trần thuật. Để trả lời cho câu hỏi dạng tính từ này, chúng ta sẽ phải nhắc lại tính từ đã được đề cập đến trong câu hỏi. Không được sử dụng そうです hoặc そうじゃありません để trả lời.', 'ペキンはさむいですか。', 'Bắc Kinh có lạnh không?', 3),
  (8, 'なーけいようし : Phần thân + な N | いーけいようし : Phần thân+い N', 'Tính từ còn được đặt trước danh từ để bổ nghĩa cho danh từ đó. Khi đứng trước danh từ, ta giữ nguyên phần thân và phần đuôi của tính từ. Lưu ý : Trong tiếng Nhật, trật tự của tính từ và danh từ bị ngược so với tiếng Việt. Tiếng Việt : Danh từ + Tính từ >', 'かなむらせんせいはしんせつなせんせいです。', 'Tính từ D anh từ', 4),
  (8, 'とても/ あまり', 'とても và あまり là những trạng từ chỉ mức độ. Cả 2 đều được đặt trước tính từ mà nó bổ nghĩa trong câu. とても được sử dụng trong câu khẳng định, nó có nghĩa là “ rất”. あまり được sử dụng trong câu phủ định, nó đi kèm với dạng phủ định thì có nghĩa là “ không ~ lắm “', 'ペキンはとてもさむいです。', 'Bắc Kinh rất lạnh .', 5),
  (8, 'N は どうですか。', 'Dạng câu hỏi này được sử dụng để hỏi về ấn tượng hay quan điểm của người nghe về thứ/ địa điểm/ con người mà người nghe đã từng gặp/ tới thăm/ trải qua.', 'にほんのせいかつはどうですか。', 'Cuộc sống ở Nhật thế nào( ra sao)?', 6),
  (8, 'N1は どんな N2 ですか。', 'Dạng câu hỏi này được sử dụng khi người nói muốn người nghe miêu tả hoặc giảng giải lại cho mình về N1. Trong câu này, N1 là một vật/ người/ địa điểm... nằm trong phạm vi của N2. Từ để hỏi どんな luôn đứng trước một danh từ .', 'ならはどんなまちですか。', 'danh từ', 7),
  (8, 'S1 が、S2', 'が là một liên từ, nó có nghĩa là “ nhưng” và được dùng để nối 2 vế của câu mà vế này có ý nghĩa tương phản với vế kia ( ngược lại với そして ). Trong trường hợp nối 2 tính từ tương phản nhau thì ta dùng mẫu A1 ですが、 A2 （ A1 và A2 là 2 tính từ ）', 'にほんのたべものはおいしいですが、たかいです。', 'Món ăn Nhật ngon nhưng đắt.', 8),
  (8, 'どれ', 'Từ để hỏi này được dùng khi người nói muốn đề nghị người nghe chọn hoặc chỉ rõ một cái từ những cái ( 3 cái trở lên ) được nêu ra 例 Anh A chỉ vào khoảng 4,5 cái ô khác nhau và hỏi anh', 'Bさんのかさはどれですか。', 'Ô của anh là cái nào?', 9),
  (9, 'N が あります/わかります N が すきです/きらいです /じょうずです /へたです', 'Trong bài 6 chúng ta đã đ ược học về những động từ chỉ hành động hay động tác có đối tượng của động từ được biểu thị bằng trợ từ を . Tuy vậy, 2 động từ あります và わかります mà ta vừa học không phải là những động từ chỉ động tác. Chúng là những động từ chỉ sự tồn tại hay chỉ khả năng của một ai đó. Vì vậy, đối tượng của 2 động từ này không được biểu thị bằng trợ từ を , mà bằng trợ từ が Tương tự, những tính từ như すきです、きらいです、じょうずです、へたです ,.. cũng cần có đối tượng của nó và những đối tượng này cũng được biểu thị bằng trợ từ が giống như 2 động từ あります và わかります . Những động từ và tính từ mà đối tượng của nó được biểu thị bằng trợ từ が theo mẫu trên là những từ dùng để biểu thị : sở thích ( hay ham muốn), năng lực và sự sở hữu. Cần lưu ý phân biệt cách dùng 2 trợ từ は và が trong mẫu câu trên ( tham khảo các ví dụ bên dưới). N1 は ： N1 là chủ thể của động từ/ tính từ . N2 が : N2 là đối tượng của động từ/tính từ. Khi chuyển các động từ và tính từ trên sang thể quá khứ hoặc phủ định, ta vẫn giữ nguyên cách chuyển như đối với các động từ và tính từ khác. Các trạng từ chỉ mức độ của tính từ あまり・とても cũng dùng như bình thường đối với các tính từ đặc biệt này.', 'わたしはイタリアりょうりがすきです。', 'Tôi thích món ăn Ý .', 1),
  (9, 'どんな + N', 'Trong bài trước, chúng ta đã học cách sử dụng “ どんな + N” để đề nghị người nghe miêu tả, giảng giải lại cho mình về tính chất, đặc điểm của N. Ngoài ra, どんな + N còn được sử dụng để đề nghị người nghe chọn một việc/ một thứ cụ thể từ một nhóm được người nói đề cập đến trong danh từ N.', '(Bさんは)どんなスポーツがすきですか。', 'Bạn thích môn thể thao nào .', 2),
  (9, 'よく/だいたい/たくさん/すこし/あまり/ぜんぜん', 'Đây là những phó từ chỉ mức độ được đặt ở trước động từ để chỉ mức độ của các động từ đó. Dưới đây là bảng thứ tự cách sử dụng của các phó từ trên : Mức độ Trạng từ + Khẳng định Trạng từ+ Phủ định Cao Thấp', 'よくわかりま', 'Hiểu rõ, rất hiểu', 3),
  (9, 'S1から、S2.', 'から được dùng để nói 2 mệnh đề hoặc 2 câu có quan hệ nhân quả với nhau. S1 là lý do của S2', 'じかんがありませんから、しんぶんをよみません。', 'Vì không có thời gian nên tôi không đọc báo .', 4),
  (9, '5．どうして', 'Từ để hỏi どうして dùng để chỉ lý do. Câu trả lời cho câu hỏi どうして phải kết thúc bằng から', 'どうしてあさしんぶんをよみませんか。', 'Tại sao buổi sáng bạn không đọc báo?', 5),
  (10, 'N が あります/います', 'Các động từ あります / います ở trên được dùng chỉ sự tồn tại hay hiện hữu của sự vật hay của con người. Khi đó, những danh từ chỉ sự vật hay con người đó trở thành chủ thể của câu và được biểu thị bằng trợ từ が . あります được dùng để chỉ sự hiện hữu của một sự vật, đồ vật vô tri hoặc tự nó không thể chuyển động được. Đồ vật và cây cối, địa điểm thuộc nhóm này.', 'コンピューターがあります。', 'Có máy vi tính.', 1),
  (10, 'N1 ( địa điểm) に N2 が あります/います', 'Địa điểm nơi N2 hiện hữu được biểu thị bằng trợ từ に . Cần phân biệt với trợ từ で dùng để chỉ địa điểm nơi xảy ra hành động.', 'わたしのへやにつくえがあります。', 'Trong phòng tôi có 1 cái bàn.', 2),
  (10, '4．N1 は N2 (địa điểm ) に あります/います', 'Trong mẫu này, người nói đưa N1 ( sự vật, con người) lên làm chủ đề của câu và nói về nơi nó hiện hữu. Khi đó, chủ đề của câu thường phải là sự vật hay con người nào mà cả người nói và người nghe đều biết hoặc đã từng được nói đến. Trợ từ đi kèm với N1 không phải là が -dùng đẻ biểu thị chủ thể nữa mà là trợ từ は - dùng để biểu thị chủ đề.', 'ホアン・キエムこに何がいますか。', 'Hồ Hoàn Kiếm có gì ?', 3),
  (10, '5．N1 ( đồ vật/ con người/ địa điểm) の N2( vị trí) = N', 'うえ、した、まえ、うしろ、みぎ、ひだり、なか、そと、となり、ちかく và あいだ là những danh từ biểu thị vị trí. Khi đó N trở thành một danh từ chỉ vị trí mới được biểu thị dựa trên vị trí gốc là vị trí của N1 và sử dụng như các danh từ chỉ vị trí thông thương khác mà ta đã học. Ở đây cần lưu ý về vị trí của N1 và N2 trong câu bị ngược so với tiếng Việt.', '例1：つくえのうえにしゃしんがあります。', 'Có tấm ảnh ở trên bàn.', 4),
  (10, '6．N1 や N2', 'Trợ từ と được sử dụng khi ta liệt kê tất cả các sự vật,con người,..trong khi đó trợ từ や mà ta học trong bài này được sử dụng để liệt kê vài vật tượng trưng trong số các sự vật hiện hữu. Đôi lúc người ta cho thêm など vào sau danh từ cuối cùng trong số các sự vật được nêu ra để nêu rõ rằng còn có nhiều sự vật, con người khác nữa cũng nằm trong nhóm đó.', 'つくえのうえにほんとペンがあります。', 'Có sách và bút ở trên bàn.', 5),
  (10, '「Từ hoặc cụm từ 」ですか。', 'Trợ từ か trong mẫu trên có chức năng dùng để xác nhận . Người nói đặt ですか vào sau từ hoặc cụm từ mà họ muốn xác nhận để xác nhận lại chúng.', 'すみません。ヴィン・コムタワーはどこですか。', 'Xin lỗi. Tháp Vincom ở đâu ?', 6),
  (10, 'N は ありませんか。', 'Cách diễn đạt 「 N は ありませんか。」 ta sẽ gặp trong hội thoại của bài này. Bằng cách sử dụng dạng phủ định ありませんか thay cho động từ あります , bạn có thể hỏi một cách lịch sự về sự tồn tại, hiện hữu của N và thể hiện cho người nghe biết một cách gián tiếp rằng bạn đã chuẩn bị tinh thần để nhận câu trả lời phủ định của họ. Luyện tập', NULL, NULL, 7),
  (11, 'Cách đếm', 'ひとつ、ふたつ、 … とお . Nh ững từ này được sử dụng để đếm các đồ vật với số lượng từ 1 đến 10. Những đồ vật có số lượng lớn hơn hoặc bằng 11 thì sẽ được đếm bằng các số đếm thông thường a,Đơn vị đếm: Khi đếm một số loại đồ vật hoặc biểu thị số lượng các đồ vật, người, người ta thêm các đơn vị đếm vào sau số từ. Các đơn vị đếm sẽ khác nhau tùy theo đồ vật. ～ 人 にん : Đơn vị đếm người ( từ 3 người trở lên). 1 người là ひとり , 2 người là ふたり , 3 người trở lên thì dùng đơn vị ~ にん như đã nói ở trên. Riêng 4 người viết là 4 人 nhưng đọc là : よにん （ không phải là よんにん） . ～ 台 ( だい ) : Đếm những vật như máy móc, xe cộ ( VD: máy vi tính, xe máy,..). ～ 枚 ( まい ) : Đếm những vật mỏng và dẹt như giấy, đĩa, áo sơmi, đĩa CD,... ～ 回 ( かい ) : Đếm số lần. ～分（～ふん・ぶん・ぷん ） : Đếm số phút. Cách đọc khác nhau tùy theo số đếm đứng ở trước. Cách biến âm giống cách nói giờ đã học ở bài trước.', '～時間:Tiếng.', '～ 日 ( にち ) : Ngày', 1),
  (11, 'Số từ ( khoảng thời gian) に ～かい V', 'Mẫu này dùng để nói bạn thường làm việc gì với tần suất bao nhiêu ?', '１かげつに２かいえいがをみます。', 'Tôi xem phim 1 tháng 2 lần.', 2),
  (11, 'Số từ だけ / N だけ', 'だけ có nghĩa là “ Chỉ”. Nó được đặt sau số từ hoặc danh từ để biểu thị rằng vật đó, thứ đó chỉ có từng đó mà thôi.', 'RikiNihongoセンターにがいこくじんがひとりだけいます。', 'Trung tâm Riki nihongo chỉ có 1 người nước ngoài (thôi).', 3),
  (12, 'Thời quá khứ của câu danh từ (N) và câu tính từ đuôi な (な - adj)', 'Để biến đổi một câu danh từ hoặc câu tính từ đuôi な từ thời không quá khứ sang thời quá khứ, ta sẽ biến đổi theo nguyên tắc sau : Không QK( hiện tại+ tương lai) Quá khứ K hẳng Đ ịnh', 'N+ですな-adj+ですN+でしたな-adj+でした', 'P hủ Đ ịnh', 1),
  (12, 'Thời quá khứ của câu tính từ đuôi い', 'Để biến đổi một câu tính từ đuôi い từ thời không quá khứ sang thời quá khứ, ta làm theo nguyên tắc sau: Không QK( Hiện tại+TL) Quá khứ K hẳng Đ ịnh Phần thân+ い＋です Phần thân+ かった＋です P hủ Đ ịnh Phần thân+ くない + です Phần thân + くなかった＋です', 'せんしゅうのパーティーはあまりたのしくなかったです。', 'Buổi tiệc tuần trước không vui lắm .', 2),
  (12, 'N1 は N2 より + “ Tính từ” です。', 'Mẫu này là mẫu so sánh hơn, dùng khi muốn nói N1 có chất lượng hoặc trạng thái được biểu thị bằng tính từ nhiều hơn so với N2. Trong sự so sánh này, N2 là vật được đưa ra làm chuẩn mực để so sánh với N1.', 'このくるまはあのくるまよりおおきいです。', 'Cái xe này to hơn (so với) cái xe kia .', 3),
  (12, 'N1 と N2 と どちらが “ Tính từ” ですか。 N1 N2 の ほうが “ Tính từ” です。', 'Mẫu này được dùng khi người nói muốn đề nghị người nghe chọn xem trong 2 lựa chọn N1 và N2 mà người nói vừa đưa ra, cái nào( người nào, con vật , thời điểm nào,...) có tính chất của “ tính từ” nhiều hơn. Từ để hỏi được sử dụng trong câu hỏi dạng này luôn là どちら , bất kể N1 và N2 là đồ vật, cọn vật hay con người,...', 'サッカーとやきゅうとどちらがおもしろいですか。', 'Bóng đá và bóng chày, môn nào hay hơn ?', 4),
  (12, 'N1 [ のなか ] で [なに/どこ/だれ/いつ] が いちばん “ Tính từ” ですか。N2 が いちばん “ Tính từ” です。', 'Mẫu này được dùng khi người nói muốn đề nghị người nghe chọn từ một số thứ ( nhiều hơn 2) mà người nói đưa ra một thứ( con người, địa điểm, thời gian) có tính chất của “ tính từ” nhất. Các phương án lựa chọn được tạo thành thì một nhóm thuộc phạm vi của N1. Khác với mẫu 4 ở trên, từ để hỏi được sử dụng ở mẫu trên thay đổi tùy thuộc vào phương án lựa chọn được đưa ra. Ví dụ: N1 là từ chỉ người thì từ để hỏi sẽ là だれ , N1 là từ chỉ thời gian thì từ để hỏi sẽ là いつ ,...', 'にほんりょうり[のなか]でなにがいちばんおいしいでか。', 'Trong các món ăn Nhật, món nào ngon nhất?', 5),
  (13, 'N が ほしい です', 'Mẫu này được dùng để diễn tả mong muốn được sở hữu hay có N của người nói. Nó cũng được sử dụng để hỏi xem người nghe muốn gì. Đối tượng của ほしい ( tức là N) được biểu thị bằng trợ từ が 、 và ほしい ( muốn) là một tính từ đuôi い . Mẫu này có cấu trúc tương tự như mẫu 「 S は N が すきです」 và 「 S は N があります」 mà ta đã học trong những bài trước. Lưu ý : ほしい chỉ được đi kèm với bổ ngữ là danh từ.', 'わたしはともだちがほしいです。', 'Tôi muốn có bạn.', 1),
  (13, 'Thể Vます ＋ たいです', 'a,Thể V ます: Các động từ ta học từ trước đến giờ đều có đuôi ます ở cuối cùng. VD : かえります、たべます、かいます、のみます ,..Trong các động từ này, thì phần trước ます được gọi là thể ます.', 'わたしはホーチミンしへいきます。', 'Tôi đi thành phố HCM.', 2),
  (13, 'N (địa điểm) へ [ Thể ます/N ] に 行(い)きます/来(き)ます/帰(かえ)ります', 'Trong bài 5, chúng ta đã học trợ từ へ dùng để biểu thị phương hướng của các động từ chỉ sự di chuyển như いきます , きます , かえります . Trong bài này, chúng ta thêm [ Thể ます /N ] + trợ từ に vào mẫu câu : N (địa điểm) へ 行きます / 来ます / 帰ります đã học để nói thêm về mục đích của việc di chuyển đó. Mục đích của việc di chuyển được biểu thị bằng trợ từ に . Danh từ N trong mẫu này phải là danh từ chỉ một động tác nào đó ( còn gọi là danh động từ , ví dụ : かいもの、べんきょう ).', 'こうべへインドりょうりをたべにいきます。', 'Tôi đi Kobe để ăn món ăn Ấn Độ .', 3),
  (13, 'N に V / N を V', 'Trợ từ に được sử dụng để chỉ đích đế n khi được sử dụng với các động từ はいります ( vào), のります ( lên xe, lên tàu,..- xem bài 16) . Còn trợ từ を được sử dụng để chỉ điểm xuất phát hoặc điểm bắt đầu khi được sử dụng với các động từ でます ( đi ra) 、おります ( xuống xe, xuống tàu,...tham khảo bài 16).', 'あのきっさてんにはいりましょう。', 'Vào quán cafe kia đi .', 4),
  (13, 'どこか / なにか', 'どこか có nghĩa là chỗ nào đó và なにか có nghĩa là cái gì đó. Khi dùng 2 từ này có thể bỏ bớt trợ từ へ hoặc を .', 'ふゆやすみはどこか（へ）いきましたか。', 'Nghỉ động bạn có đi đâu không ?', 5),
  (13, 'ごちゅうもん', 'Cũng giống như お（おくに） , tiếp đầu ngữ ご được thêm vào trước danh từ (thường là danh từ cấu tạo từ 2 chữ Hán) để thể hiện sự tôn trọng đối với người nghe.', 'ごちゅうもんは？', 'Anh gọi gì ạ?', 6),
  (14, 'Biến đổi động từ', 'Không giống như tiếng Việt, một động từ trong tiếng Nhật biến đổi rất đa dạng(tổng cộng có khoảng 10 dạng) tùy thuộc vào vai trò và ý nghĩa của nó trong câu ( quá khứ, hiện tại, bị động, chủ động,...). Các động từ trong tiếng Nhật được chia làm 3 nhóm dựa theo cách biến đổi của chúng. Vì vậy, để biến đổi đúng được động từ trong tiếng Nhật, điều quan trọng nhất là phải phân biệt được động từ đó ở nhóm nào trong 3 nhóm trên.', NULL, NULL, 1),
  (14, 'Các nhóm động từ', 'Động từ nhóm I: Nhóm này bao gồm những động từ có âm tận cùng của phần thể ます là những âm thuộc hàng い ( き、ぎ、し、ち ,...). Tuy nhiên, có một số động từ đặc biệt tuy có âm tận cùng của phần thể ます là い nhưng không thuộc nhóm I này mà thuộc nhóm II. Vì vậy sẽ phải ghi nhớ những động từ này để tránh bị nhầm lẫn. (Chi tiết tham khảo phụ lục đính kèm cuối bài từ trang 178 đến trang 183).', 'かきますとりますおくりますのみますやすみますはいります', 'Động từ nhóm II:', 2),
  (14, 'Thể て', 'Thể của động từ có kết thúc bằng て hoặc で thì được gọi là thể て . Cách biến đổi một động từ từ thể ます sang thể て khác nhau tùy thuộc động từ đó thuộc nhóm I, II hay III. ( Chi tiết tham khảo phần phụ lục đính kèm và phần luyện tập A1, trang 116, bài 14, sách giáo trình ). a, Nhóm I : Nhóm I : Tùy thuộc vào âm tận cùng của phần thể ます mà cách biến đổi thể て của những động từ thuộc nhóm này cũng khác nhau. Cụ thể : Những động từ có âm tận cùng của phần thể ます là い、ち、り thì:', 'Vて＝Thểます－い/ち/り＋って', 'Động từ', 3),
  (14, 'Thểて + ください', 'Mẫu này dùng để đề nghị, yêu cầu hay khuyến khích người nghe làm một điều gì đó.Đương nhiên, nếu người nghe là người lớn tuổi hơn hoặc có địa vị cao hơn mình thì tránh sử dụng mẫu này để đưa ra lời đề nghị, yêu cầu đối với người đó. Các câu dưới đây lần lượt là các ví dụ về cách sử dụng mẫu trên để đề nghị, yêu cầu hoặc khuyến khích :', 'すみませんが、このかんじのよみかたをおしえてください。', 'Xin lỗi, hãy dạy tôi cách đọc chữ Hán này.', 4),
  (14, 'Thểて＋います', 'Mẫu này được sử dụng để diễn tả một hành động hoặc một động tác nào đó đang trong quá trình tiếp diễn.', 'ソンさんはいまでんわをかけています。', 'Bây giờ anh Sơn đang gọi điện thoại.', 5),
  (14, 'Thể ます ＋ ましょうか', 'Mẫu này được sử dụng khi người nói đề nghị đươc làm một cái gì đó để giúp người nghe.', 'あしたもきましょうか。', 'Ngày mai tôi cũng đến chứ ?', 6),
  (14, 'S1 が、S2', 'Các bạn đã học liên từ が trong bài 8 dùng để nối 2 mệnh đề có ý nghĩa đối lập nhau. Tuy nhiên, trong cách diễn đạt này, thì liên từ が được sử dụng trong những câu mào đầu như しつれいですが、すみませんが ( những câu người nói dùng để bắt đầu câu chuyện) mất đi ý nghĩa nguyên thủy của nó mà chỉ đơn thuần có chức năng nối 2 mệnh đề của câu.', 'しつれいですが、おなまえは?', 'Xin lỗi( xin thất lễ), tên bạn là gì?', 7),
  (14, 'N が V', 'Khi miêu tả một hiện tượng tự nhiên , chủ thể của hiện tượng đó được biểu thị bằng trợ từ が', 'あめがふっています。', 'Trời đang mưa .', 8),
  (15, 'Vてもいいです', 'Mẫu này được dùng để biểu đạt sự cho phép :', '例1：しゃしんをとってもいいです。', 'Bạn có thể( được phép) chụp ảnh .', 1),
  (15, 'Vては いけません', 'Mẫu này được dùng để biểu đạt sự cấm đoán.', '例1：この川でおよいではいけません。', 'Không được bơi ở con sông này.', 2),
  (15, 'Vて います', '“ V ています ” ngoài cách sử dụng đã học ở bài 14 còn có thể sử dụng để biểu đạt trạng thái tiếp diễn là kết quả của một hành động trong quá khứ.', '例1：わたしはけっこんしています。', 'Tôi đã kết hôn .', 3),
  (15, 'Vて います (Những hành động có tính lâu dài)', 'Mẫu V ています còn được sử dụng để biểu đạt một thói quen, một tập quán ( nghĩa là một hành động được lặp đi lặp lại nhiều lần trong một thời gian dài). Bạn cũng có thể dùng mẫu này để nói về nghề nghiệp của một ai đó, như trong ví dụ 3 và 4. Vì thế, nếu được hỏi câu hỏi: おしごとは なんですか thì bạn có thể sử dụng mẫu này để trà lời.', '例1：FPTはコンピューターソフトをつくっています。', 'FPT sản xuất phần mềm máy tính .', 4),
  (15, 'しりません', 'Thể phủ định của しって います là しりません .', '例1：A:しやくしょのでんわばんごうをしっていますか。(X）しやくしょのでんわばんごうをしりますか。―＞khôngdùng', 'Bạn có biết số điện thoại của tòa thị chính không?', 5),
  (16, 'V1て、V2て、～', 'Để nối các câu động từ với nhau, ta có thể sử dụng thể て . Khi có nhiều hơn hoặc bằng 2 hành động liên tiếp xảy ra, ta sử dụng thể て để sắp xếp chúng theo thứ tự xảy ra hành động. Thì của các câu phức dạng này được quy định bởi thì của động từ ở cuối câu.', 'おおさかででんしゃにのります。しんおおさかでしんかんせんにのりかえます。とうきょうでおります。おおさかででんしゃにのって、しんおおさかでしんかんせんにのりかえて、とうきょうでおります', 'Tôi lên tàu điện ở Osaka, chuyển sang Shinkansen ở Shin Osaka rồi xuống ở ga Tokyo', 1),
  (16, 'V1て + から, V2.', 'Ta dùng mẫu này để nói về quan hệ trước sau về mặt thời gian của 2 hành động. Ở đây người nói muốn nhấn mạnh rằng hành động V2 được tiến hành sau khi hành động V1 đã kết thúc. Thì của câu dạng này được quy định bởi thì của động từ ở cuối câu.', '例1：でんきをけします。それから、きょうしつをでます。でんきをけしてから、きょうしつをでます。す。', 'Tôi tắt điện, sau đó ra khỏi phòng học .', 2),
  (16, 'い - adj ( ～い ) => ～くて、～', 'Khi muốn nối 1 câu tính từ đuôi い và một câu tính từ khác, ta bỏ 「いです」 của tính từ đuôi い đi và thêm vào sau nó phần 「～くて」 rồi nối với câu còn lại. Thì của câu phức dạng này được quy định bởi thì của tính từ ở cuối câu.', 'おおきーいです－＞おおきーくてちいさーいです－＞ちいさーくていーいです－＞よくて例1：ベトナムりょうりはおいしいです。そしてやすいです。ベトナムりょうりはおいしくて、やすいです。', 'Đ ồ ‌ ‌ ă n ‌ ‌ Việt ‌ ‌ Nam ‌ ‌ ngon ‌ ‌ v à ‌ ‌ rẻ ‌.', 3),
  (16, '[N/な- adj] + で、～', 'Khi muốn nối 1 câu tính từ đuôi な hoặc một câu danh từ với một câu tính từ hoặc danh từ khác, ta thay 「です」 của tính từ đuôi な hoặc danh từ bằng 「で」 rồi nối với câu còn lại. Thì của câu phức dạng này được quy định bởi thì của tính từ hoặc danh từ ở cuối câu.', '例1：カリナさんはインドネシア人です。カリナさんはなごやだいがくのりゅうがくせいです。カリナさんはインドネシア人で、なごやだいがくのりゅうがくせいです。', 'Chị ‌ ‌ Karina ‌ ‌ l à ‌ ‌ ng ư ời ‌ ‌ Indonesia ‌ ‌ v à ‌ ‌ l à ‌ ‌ sinh ‌ ‌ vi ê n ‌ ‌ đ ại ‌ ‌ học ‌ ‌ Nagoya ‌.', 4),
  (16, 'N1 は N2が “ Tính từ”', 'Mẫu này được sử dụng để nói về thuộc tính, đặc điểm của một vật hoặc một người nào đó. Trong mẫu này, N2 là chủ đề của câu và được biểu thị bằng trợ từ は , còn N2 là chủ thể của tính từ ( tức chủ thể của thuộc tính, đặc điểm được đề cập đến) và được biểu thị bằng trợ từ が . N2 là một bộ phận của N1.', '例1：マリアさんはかみがながいです。', 'Chị Maria tóc dài.', 5),
  (16, 'どうやって', 'どうやって được sử dụng để hỏi về cách, phương pháp để làm một việc gì đó. Để trả lời cho câu hỏi này, ta có thể sử dụng mẫu câu thứ 1 đã học ở bài này.', 'おおさかからとうきょうまでどうやっていきますか。', 'Đi từ Osaka đến Tokyo bằng cách nào ?', 6),
  (16, 'どの N', 'Ở bài 2, chúng ta đã học các từ この、その、あの . Từ để hỏi của các từ này là どの . Nó được dùng để đề nghị người nghe chỉ định ra một thứ ( hoặc 1 người) từ những vật mà người nghe đưa ra.', 'なりたさんはどのひとですか。', 'Chị Narita là người nào ?', 7),
  (17, 'Thể ない', 'Ngoài thể て và thể ます đã học phần trước, động từ trong tiếng Nhật còn một dạng biến hóa khác là thể ない . Sau đây là cách tạo thể ない của một động từ từ thể ます của nó. a. Nhóm I: Các động từ thuộc nhóm này đều có âm cuối của phần thể ます là những âm thuộc hàng い(い、き、し、ち、...) . Để tạo thể ない của những động từ nhóm I này, ta chỉ việc thay thế âm đó bằng âm tương ứng ở hàng あ ( VD: き => か、し => さ、ち => た、...) . Riêng những từ có âm tận cùng của phần thể ます là い thì sẽ được thay bằng âm わ (chứ không phải あ ). Chi tiết tham khảo bảng phụ lục động từ đã phát ở bài 14. Thể ます Thể ない', 'すわ（ない）', 'b. Nhóm II:', 1),
  (17, 'Thể ない + ないで ください', 'Mẫu này được dùng để đề nghị, dặn dò ai đó đừng làm một việc nào đó. Cũng giống như V てください , đây là câu mệnh lệnh nên tránh dùng với người trên.', 'わたしはげんきですから、しんぱいしないでください。', 'Tôi khỏe, vì thế đừng lo lắng.', 2),
  (17, 'Thể ない＋ なくても いいです', 'Mẫu này dùng để biểu đạt sự không cần thiết của hành động được diễn tả bằng động từ.', 'あしたこなくてもいいですよ。', 'Ngày mai bạn không cần phải đến đâu.', 3),
  (17, 'Thể ない＋ なければ なりません', 'Mẫu này được dùng để biểu đạt một việc được coi như là nghĩa vụ phải làm, bất chấp người làm có muốn như vậy hay không.', 'わたしはくすりをのまなければなりません。', 'Tôi phải uống thuốc.', 4),
  (17, 'N (đối tượng) は', 'Trong bài 6, các bạn đã được học về trợ từ を được đính kèm ngay sau đối tượng trực tiếp của các động từ. Trong bài này, chúng ta sẽ học cách đưa các đối tượng đó lên làm chủ đề bằng cách thay thế trợ từ を bằng trợ từ は .', 'ここににもつをおいてください。', 'Hãy để hành lý ở đây.', 5),
  (17, 'N (thời gian) までに V', 'Thời điểm được biểu thị bằng までに là thời hạn cuối mà một hành động hay một công việc phải được tiến hành. Có nghĩa là, hành động hay công việc phải được tiến hành trước thời hạn được chỉ định bởi までに .', 'かいぎは5時までにおわります。', 'Cuộc họp sẽ kết thúc trước 5 giờ.', 6),
  (18, 'Thể từ điển（じしょけい)', 'Đây là dạng cơ bản của động từ . Các động từ được đưa vào trong từ điển dưới dạng này, chính vì thế nó có tên gọi là thể từ điển. Sau đây là cách tạo thể từ điển của động từ (Xem bài 18, trang 148, phần Luyện tập A1). Nhóm 1: Những động từ trong nhóm này luôn có âm cuối phần thể ます là những âm thuộc hàng い . Để tạo thể từ điển của động từ, ta chỉ việc thay thế âm đó bằng âm tương ứng ở hàng う .', 'あいーます――＞あうのみーます――＞のむかいーます――＞かうよびーます――＞よぶ。', 'Nhóm 2 : Để tạo thể từ điển của những động từ nhóm II, ta chỉ việc thêm る vào sau phần thể ます.', 1),
  (18, '[Danh từ/ Vる こと] ができます ( Vる：Kí hiệu viết tắt của động từ ở thể từ điển)', 'できます là động từ dùng để biểu đạt năng lực hay khả năng. Danh từ hoặc V ること (Thể từ điển của động từ + こと ) đứng trước trợ từ が biểu thị nội dung của năng lực hay khả năng đó. Danh từ: Những danh từ được đặt trước が hầu hết là những danh động từ diễn tả một hành động, động tác( VD: lái xe, nhảy, trượt tuyết,...). Những danh từ đi kèm với hành động はなす như にほんご、えいご、 ... hay những danh từ đi kèm với hành động ひく như ピアノ、ギター cũng có thể được sử dụng trong trường hợp này.', 'ハイさんはにほんごができます。', 'Anh Hải có thể nói tiếng Nhật/ Anh ấy biết tiếng Nhật.', 2),
  (18, 'わたしの しゅみは [N/ Vること] です', 'Trong câu trên, người nói chỉ nói sở thích của mình là bóng đá nói chung, tức là có thể hiểu là thích xem bóng đá, cũng có thể hiểu là thích chơi bóng đá,... --> không cụ thể.', 'わたしのしゅみはサッカーです。', 'Sở thích của tôi là bóng đá .', 3),
  (18, '[V1る/ Nの/ Số từ chỉ một khoảng thời gian] まえに、 V2', 'Động từ : Mẫu câu này được dùng khi bạn muốn nói rằng hành động V2 xảy ra trước khi hành động V1 được tiến hành. Vì vậy, ngay cả khi thì của động từ V2 ở dạng quá khứ hoặc tương lai thì động từ V1 vẫn luôn ở thể từ điển ( Vì trước hành động V2 thì hành động V1 vẫn chưa xảy ra).', 'レポートをかくまえに、しりょうをあつめなければなりません。', 'Phải tập hợp tài liệu trước khi viết báo cáo .', 4),
  (18, 'なかなか', 'Khi なかなか đi kèm với dạng phủ định thì nó có nghĩa là “ không dễ dàng”, “ mãi mà không”.', 'なかなかかんじをおぼえることができません。', 'Mãi mà không nhớ được chữ Hán .', 5),
  (18, 'ぜひ', 'ぜひ được sử dụng kèm với những mẫu câu diễn tả sự mong muốn, yêu cầu như : ほしいです、 V たいです、 V てください、 V ましょう để nhấn mạnh mong muốn, yêu cầu đó.', 'ぜひほっかいどうへいきたいです。', 'Tôi rất muốn đến Hokkaido .', 6),
  (19, 'Thể た', 'Trong bài này, chúng ta sẽ học về thể た của động từ. Để tạo thể た của động từ, ta chỉ việc thay âm て (hoặc で ) trong thể て của động từ đó tương ứng bằng âm た（ hoặc だ） . Thể ます Thể て Thể た', NULL, NULL, 1),
  (19, 'V たことが あります (Vた: viết tắt của động từ ở thể た)', 'Mẫu này được dùng để nói về kinh nghiệm mà một ai đó đã gặp trong quá khứ. Về cơ bản, thì mẫu này giống với mẫu S1 は N があります ( tức là あります với nghĩa là sở hữu) mà các bạn đã học trong bài 9. Ở đây, phần nội dung của kinh nghiệm đó đ ược diễn tả bằng cụm danh từ hóa V たこと .', 'やまださんはうまにのったことがあります。', 'Anh Yamada đã từng cưỡi ngựa .', 2),
  (19, 'Vたり、 Vたり します', 'Ở bài 10, chúng ta đã học cách để liệt kê một vài vật( hoặc người) tượng trưng trong số các sự vật hiện hữu bằng cách sử dụng mẫu : （～や～など） . Tuy nhiên, mẫu này chỉ được dùng khi ta liệt kê các danh từ . Trong bài này, chúng ta sẽ học cách liệt kê một vài hành động trong số một loạt các hành động đã hoặc sẽ diễn ra. Thì của câu dạng này được quy định bởi động từ します ở cuối câu.', 'どようびはおんがくをきいたり、えいがをみたりします。', 'Thứ 7 tôi nghe nhạc, xem phim,...v.v.. .', 3),
  (19, '[Tính từ đuôi い（～い）→ く/ Tính từ đuôi な（～な）→ に/ N に] なります', 'なります có nghĩa là “ trở thành”, “ trở nên”,... dùng để chỉ sự thay đổi một tình trạng hay điều kiện. Lưu ý : Không chỉ riêng khi đứng trước động từ “ なります ”mà cả khi đứng trước các động từ khác thì tính từ và danh từ cũng biến đổi theo quy tắc trên.', 'ここはにぎやかですね。', 'Ở đây nhộn nhịp nhỉ.', 4),
  (19, 'そうですね', 'Câu nói này được sử dụng khi bạn muốn thể hiện sự đồng ý hoặc đồng tình với người nói chuyện cùng. Khác với cách diễn dạt そうですか ( hạ giọng ở cuối câu)- là cách diễn đạt nhằm xác nhận hoặc cảm thán sau khi nhận được những thông tin mà mình không biết, そうですね được sử dụng để diễn tả sự đồng ý hoặc đồng tình với người nói chuyện cùng khi họ nêu ra những điều mà bạn đã biết hoặc cũng cảm thấy giống họ :', 'さむくなりましたね。', 'Lạnh rồi nhỉ.( Trở nên lạnh rồi nhỉ)', 5),
  (20, 'Thể văn lịch sự và thể văn thông thường', 'Trong tiếng Nhật có 2 cách nói: các nói lịch sự và cách nói thông thường. Các danh từ, tính từ đuôi い , tính từ đuôi な , động từ được sử dụng như vị ngữ của câu mà ta học từ trước đến nay đều được đặt ở cuối câu có です (hoặc các biến thể của です：でした、じゃありません、じゃありませんでした ) 、 ます (hoặc các biến thể của ます：ました、ません、ませんでした ) đi theo sau. Câu văn có tận cùng là です、ます và các biển thể của chúng được gọi là thể văn lịch sự . Cho đến bài 19, chúng ta đã học cách chia động từ ở nhiều thể như thể ない、 thể た , thể từ điển,… Các thể này được sử dụng với các nhóm từ ngữ theo sau như:', 'わたしはすしをたべたいです。', 'Tôi muốn ăn Sushi .', 1),
  (20, 'Sử dụng thể văn thông thường hay thể văn lịch sự ?', 'Thể văn lịch sự có thể sử dụng được bất cứ lúc nào, bất cứ đâu và với bất cứ ai. Thể lịch sự được sử dụng nhiểu nhất trong hội thoại hàng ngày giữa những người không phải bạn thân với nhau. Nó cũng được sử dụng khi bạn nói chuyện với ai đó mới gặp lần đầu, với người trên và thậm chí với cả những người cùng độ tuổi nhưng không thân thiết lắm. Thể lịch sự cũng có thể được sử dụng khi ai đó nói với người trẻ tuổi hơn mình hoặc ở cấp bậc thấp hơn mình nhưng không có quan hệ thân thiết. Còn thể văn thông thường thì được sử dụng khi nói chuyện với bạn thân, bạn học hoặc với những người thân trong gia đình. Cần phải biết rõ mối quan hệ giữa mình với người đang nói chuyện như thế nào( về tuổi tác, về mức độ thân thiết,…) để quyết định khi nào nên sử dụng thể thông thường cho phù hợp. Nếu bạn sử dụng thể thông thường không đúng chỗ thì có thể trờ thành thất lễ nên phải hết sức lưu ý. Thể văn thông thường được sử dụng phổ biến trong văn viết . Sách, báo, nhật kí,, đều được viết ở thể văn thông thường. Còn hầu hết thư từ đều được viết ở thể văn lịch sự.', NULL, NULL, 2),
  (20, 'Hội thoại bằng thể thông thường', 'Ở thể thông thường, trong câu hỏi, ta thường lược bỏ か đi. Và để thể hiện đó là câu hỏi thì ta sẽ lên giọng ở cuối câu.', 'こんばんひま？', 'Tối nay có rỗi không ?', 3),
  (20, 'けど', 'けど có chức năng giống が , dùng để nối 2 mệnh đề với nhau (Xem lại chức năng của が ở bài 8, mục 7 và bài 14, mục 7). Nó thường được sử dụng trong hội thoại. けど có thể đi cùng với cả thể văn thông thường lẫn thể văn lịch sự. Khi đi cùng với thể văn lịch sự, trước けど phải có です .', 'そのカレーライス（は）おいしい？', 'Món cơm cari kia ngon không?', 4),
  (21, '（Thể văn thông thường）と おもいます', 'Mẫu này được dùng để biểu thị phỏng đoán hay quan điểm của mình về một việc gì đó. Thông tin ( các phỏng đoán, quan điểm) được diễn tả bởi động từ おもいます được biểu thị qua trợ từ と a) Biểu thị sự phỏng đoán:', 'あしたあめがふるとおもいます。（O）', 'Tôi nghĩ là ngày mai trời mưa.', 1),
  (21, '“Câu nói” と いいます ( Thể văn thông thường )', 'Mẫu này được dùng để trích dẫn lại lời nói của người khác. Nội dung trích dẫn được diễn tả bởi động từ いいます cũng được biểu thị qua trợ từ と . a) Khi trích dẫn trực tiếp những câu mà người khác nói hoặc đã nói, ta nhắc lại nguyên văn điều mà họ nói trong ngoặc 「 」 theo cấu trúc sau :', 'ねるまえに「おやすみなさい」といいます。', 'Người ta nói “ Oyasuminasai” trước khi ngủ .', 2),
  (21, 'V | Tính từ đuôi い | Tính từ đuôi な | Thể văn thông thường（～だ）', 'Khi người nói nghĩ rằng người nghe cũng có sự hiểu biết nhất định về chuyện mình nói và kỳ vọng rằng người nghe sẽ đồng ý với quan điểm của mình, でしょう ( với giọng đọc cao ở cuối câu ) được thêm vào để xác nhận sự đồng ý của người nghe. Câu văn trước でしょう được chuyển sang thể văn thông thường .', 'あしたパーティーにいくでしょう？', 'Mai bạn cũng đi party đúng không?', 3),
  (21, 'N1 (địa điểm) で N2 が あります。', 'Khi N2 là danh từ biểu thị một sự kiện nào đó ( ví dụ như : buổi tiệc, buổi hòa nhạc, trận đấu,tai nạn, thiên tai,..) thì あります có nghĩa là “ diễn ra”, “ xảy ra” hoặc là “ được tổ chức”.', 'とうきょうで日本とブラジルのサッカーのしあいがあります.', 'Trận bóng đá giữa Nhật Bản và Brazil diễn ra ở Tokyo. .', 4),
  (21, 'N ( dịp) で', 'Để diễn tả một hành động xảy ra trong một dịp nào đó thì dịp đó được biểu thị bởi trợ từ で .', '例1：かいぎでなにかいけんをいいましたか。', 'Bạn có nói ý kiến gì trong buổi họp không?', 5),
  (21, 'NでもV', 'でも được sử dụng để đưa ra một ví dụ từ nhiều thứ cùng loại ( ví dụ như trong ví dụ dưới đây là đồ uống) khi muốn khuyến khích, khuyên ai đó làm điều gì đó hoặc khi muốn đề xuất việc gì.', 'ちょっとビールでものみませんか', 'Uống bia hay cái gì đấy không ?', 6),
  (21, 'Thể ない＋ないと...', 'Các diễn đạt này là cách giản lược của mẫu : “Thể ない＋ないといけません ”. Cách dùng và nghĩa của “ Thể ないといけません ” gần giống với mẫu“ Thể ない + なければ なりません ” mà các bạn đã học trong bài 17.Tuy vậy, mẫu “ Thể ないといけません ” thường được dùng trong văn nói chứ hầu như không được dùng trong văn viết.', 'もうかえらないと...', 'Tôi phải về bây giờ.', 7),
  (22, 'Mệnh đề định ngữ', 'Trong bài 2 và bài 8, chúng ta đã học cách dùng danh từ hoặc tính từ để bổ nghĩa cho danh từ: ハイさんの うち : Nhà của anh Hải', 'おんがくを(MĐĐN)きいている人N(はハイさんです）', 'Người đang nghe nhạc ( là anh Hải).', 1),
  (22, 'Thể từ điển + じかん/やくそく/ようじ', 'Khi muốn biểu đạt về thời gian để làm một việc gì đó, bạn có thể đặt động từ ở thể từ điển trước じかん để bổ nghĩa :', 'わたしはあさごはんをたべるじかんがありません。', 'Tôi không có thời gian để ăn sáng', 2),
  (23, 'Động từ, tính từ đuôi い ở とき、～ : Mệnh đề trạng', 'とき nối 2 mệnh đề của câu. Mệnh đề có chứa とき là mệnh đề trạng ngữ chỉ thời điểm khi xảy ra hành động hay tình trạng được đề cập đến ở mệnh đề chính. Như đã trình bày ở trên, các động từ, tính từ đuôi い ,tính từ đuôi な ,danh từ khi kết hợp với とき thì theo các nguyên tắc giống như khi chúng kết hợp để bổ nghĩa cho danh từ( bài 22, vì とき cũng là một danh từ).', 'としょかんで本をかりるとき、カードがいります。', 'Khi mượn sách ở thư viện, cần có thẻ.', 1),
  (23, 'Thể từ điển（Vる) , Thể た（Vた）', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'くにへかえるとき、かばんをかいました。', 'Tôi đã mua cặp sách lúc ( chuẩn bị/trên đường) về nước.', 2),
  (23, 'Thể từ điển＋と', 'Khi muốn diễn tả rằng một sự việc hay một hành động xảy ra sẽ kéo theo kết quả tất yếu là một sự việc hay một hành động khác cũng phải xảy ra theo thì người ta sẽ dùng と để nối các mệnh đề đó với nhau.', 'ふゆになると、さむくなります。', 'Cứ sang mùa đông là trời trở lạnh.', 3),
  (23, 'N が tính từ/ động từ', 'Khi miêu tả một tình trạng hoặc một cảnh tượng nào đó như nó vốn có thì chủ thể cũng được biểu thị bằng trợ từ が：', 'おとがちいさいです。', 'Âm thanh bé.', 4),
  (23, 'N ( địa điểm) を V ( động từ miêu tả sự di chuyển)', 'Trợ từ được sử dụng để biểu thị khu vực mà một người hoặc một vật nào đó chuyển động trong đó. Những động từ được sử dụng trong mẫu này là các động từ miêu tả sự di chuyển như :', 'さんぽします、わたります、あるきます,...こうえんをさんぽします。', 'Tôi đi dạo công viên.', 5),
  (24, 'くれます', 'Trong bài 7, các bạn đã được học động từ あげます với nghĩa là cho, tặng và もらいます với nghĩa là nhận. Ta có sơ đồ sau : ü もらいます： Đứng từ vị trí của người nhận: ü あげます： Đứng từ điểm nhìn của người cho :', 'わたしはさとうさんにはなをあげました。', 'Tôi tặng hoa chị Satou.', 1),
  (24, 'Thể て + あげます, もらいます, くれます', 'あげます、もらいます và くれます cũng được sử dụng để biểu đạt việc cho hoặc nhận các hành động giống như với các đồ vật bình thường. Chúng chỉ sự việc ai làm một hành động gì đó cho ai nhằm xác định rõ chiều hướng của hành động đó cũng như để biểu lộ một hảo ý hay một sự cảm ơn. Trong trường hợp này, hành động được đề cập đến được biểu thị bằng động từ ở thể て .', 'Thểて＋あげます：', 'ü Đứng từ điểm nhìn của người cho hành động .', 2),
  (25, 'Thể quá khứ thông thường +ら', 'Khi ら được thêm vào sau thể quá khứ thông thường của các động từ, tính từ,danh từ.. thì nó sẽ biến mệnh đề đứng trước nó thành mệnh đề biểu hiện điều kiện. Ta sử dụng mẫu này khi muốn bày tỏ lập trường, ý kiến, yêu cầu, tình trạng của mình trong một điều kiện nào đó.', 'おかねがあったら、りょこうします。', 'Nếu có tiền, tôi sẽ đi du lịch.', 1),
  (25, 'Vた＋ら、～', 'Mẫu này được sử dụng khi người ta muốn nói rằng,để cho một hành động hay một tình trạng nào đó được đề cập đến ở mệnh đề chính được tiến hành thì điều kiện phải có là hành động ở mệnh đề phụ phải hoàn tất. Thì của mệnh đề chính luôn ở thì không quá khứ.', '10時になったら、でかけましょう。', 'Đến 10 giờ thì chúng ta sẽ đi ra ngoài.', 2),
  (25, 'Thể て | Tính từ đuôi い, な', 'Trái ngược với mẫu : “ Thể quá khứ thông thường + ら ,~” diễn tả một điều kiện thuận ( tức là khi điều kiện đó xảy ra thì sẽ dẫn đến tình trạng, hành động ở mệnh đề chính), mẫu này được dùng để diễn tả một điều kiện nghịch. Mẫu này được dùng khi muốn nói về việc một hành động hay một sư kiện được cho là đương nhiên sẽ phải xảy ra theo điều kiện đã có nhưng kết quả xảy ra lại trái ngược với lẽ thường hoặc với những gì mà ta kì vọng.', 'にちようびでもはたらきます。', 'Mặc dù là chủ nhật nhưng tôi vẫn làm việc.', 3),
  (25, 'もし và いくら', 'もし được sử dụng trong câu “ Thể quá khứ thông thường + ら ” và もし được sử dụng trong câu ～ても（～でも） để báo cho người nghe biết rằng câu đó là câu điều kiện. もし bao hàm ý nhấn mạnh về giả thuyết của người nói, trong khi đó いくら thì nhấn mạnh về mức độ điều kiện.', 'もし1おくえんあったら、いろいろなくにをりょこうしたいです。', 'Nếu có 100 triệu Yên thì tôi sẽ đi du lịch nhiều nước.', 4),
  (25, 'N が', 'Trong các bài trước, chúng ta đã được lưu ý rằng, chủ thể của mệnh đề phụ trong câu được biểu thị bằng trợ từ が . Các mệnh đề phụ sử dụng たら、ても、とき、と、まえに、 và mệnh đề chỉ nguyên nhân から thì chủ thể của cũng được biểu thị bằng trợ từ が như dưới đây:', 'ともだちがくるまえに、へやをそうじします。', 'Tôi dọn nhà trước khi bạn bè đến.', 5),
  (26, 'Vていただけませんか', 'Mẫu này được sử dụng khi muốn nhờ ai làm giúp chuyện gì đó một cách lịch sự. Hành động mà người nói muốn người nghe làm giúp được biểu thị bằng động từ V. Đây là cách yêu cầu lịch sự hơn so với ～てください ta đã học trước đây. Vì vậy, khi muốn nhờ người trên làm giúp việc gì đó thì nên sử dụng mẫu này thay vì sử dụng ～てください：', '先生、この漢字の読み方を教えていただけませんか。', 'Thầy có thể dạy em cách đọc chữ Hán này được không ạ?', 1),
  (26, 'Từ để hỏi + Vたら いいですか', '~ たら いいですか được sử dụng khi người nói muốn đề nghị người nghe cho mình một lời khuyên hay một chỉ thị về một việc gì đó mà người nói phải hoặc nên làm. Trong VD1, người nói muốn mua một chiếc máy ảnh nhưng không biết nên mua ở đâu nên anh ta đề nghị người nghe giới thiệu cho mình một cửa hàng tốt để mua.', 'どこでカメラを買ったらいいですか。', 'Tôi nên mua máy ảnh ở đâu?', 2),
  (26, 'Thể thông thường + んです', 'Lưu ý : Nếu trước んです là danh từ hay tính từ đuôi な thì thay だ ở phần cuối câu văn ở thể thông thường bằng な trước khi thêm vào sau đó んです . ～ んです là một cách diễn đạt dùng để giải thích nguyên nhân, lý do, …. của một hành động, tình huống.... ～ んです được sử dụng khi nói còn ～のです được sử dụng khi viết. Trong hội thoại của người Nhật thường rất hay xuất hiện ～んです , vì thế, mà khi chúng ta nghe sẽ cảm tưởng như thể văn lịch sự 「です / ます」 ít được sử dụng. Các cách sử dụng của ～ んです cụ thể như sau :', '～んですか', 'Mẫu này được dùng trong các trường hợp sau :', 3),
  (26, 'N( đối tượng) は [(好きです/嫌いです) / (上手です/下手です) / あります]', 'Trong giáo trình Minna no Nihongo I, ở bài 10 và 17, bạn đã được học là chủ thể của hành động và các đối tượng của hành động mà được biểu thị bằng trợ từ を có thể được đưa lên làm chủ đề của câu và được làm nổi bật bằng trợ từ は . Các đối tượng của tính từ và động từ có trợ từ gốc là が cũng có thể được nhấn mạnh bằng cách sử dụng trợ từ は như ở ví dụ trên.', '運動会に参加しますか。', 'Bạn có tham gia hội thao không?', 4),
  (27, 'Thể khả năng của động từ', 'Cách tạo động từ khả năng : Đối với động từ nhóm I : Những động từ trong nhóm này luôn có âm cuối phần thể ます là những âm thuộc hàng い . Để tạo thể khả năng của động từ, ta chỉ việc thay thế âm đó bằng âm tương ứng ở hàng え .', 'あい-ます→あえ-ますのみ-ます→のめ-ますかい-ます→かえ-ますよび-ます→よべ-ます', 'Đối với động từ nhóm II : Để tạo thể khả năng của động từ nhóm II, ta thêm られ vào sau phần thể ます của động từ.', 1),
  (27, 'Câu văn có động từ khả năng', '* Động từ khả năng không diễn tả hành động mà dùng để chỉ khả năng thực hiện hành động đó. Như các bạn đã học trước đây, đối tượng của các tha động từ ( はなします、たべます、あらいます、 ….) được biểu thị bằng trợ từ を , nhưng khi các tha động từ này biến đổi sang dạng khả năng, thì đối tượng của chúng thông thường sẽ được biểu thị bằng trợ từ が .', '私は日本語を話します。', 'Tôi nói tiếng Nhật.', 2),
  (27, '見(み)えます và 聞(き)こえます', 'Thể khả năng của động từ みます là みられます , và của ききます là きけます . Chúng được dùng để biểu đạt việc ý chí muốn thấy, muốn nghe của chủ thể có thể được thực hiện . Nghĩa của chúng tương tự như : みることができます và きくことができます .', '新宿で今くろさわのえいがが見られます。', 'Bạn có thể xem phim của Kurosawa ở Shinjuku bây giờ.', 3),
  (27, 'できます', 'Ở các bài trước, chúng ta đã học động từ できます với nghĩa là có thể. Ngoài nghĩa trên できます còn có các nghĩa khác là : “ hoàn thành”, “ được làm xong”, “ phát sinh”,…', '駅の前に大きいスーパーができました？', 'Ở trước ga có một siêu thị lớn vừa được hoàn thành.', 4),
  (27, 'は', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', '私が学校で英語を勉強しています。私は学校で英語を勉強しています。英語は学校で勉強しています。学校では英語を勉強しています。私の学校にはアメリカ人の先生がいます。', 'Ở trường của tôi thì có giáo viên người Mỹ.', 5),
  (27, 'も', 'Giống như cách sử dụng trợ từ は đã được nói đến ở trên, trợ từ も có thể thay thế cho trợ từ gốc khi nó là を hoặc が , còn khi trợ từ gốc là các trợ từ khác thì phải giữ nguyên trợ từ gốc đó đồng thời thêm も vào sau trợ từ gốc. Tuy nhiên trong trường hợp trợ từ gốc là [ へ ] thì nó cũng có thể được lược bỏ.', 'ハイさんは英語が話せます。フランス語も話せます。', 'Anh Hải có thể nói tiếng Anh. Anh ấy cũng nói được cả tiếng Pháp.', 6),
  (27, 'しか', 'しか đi kèm sau các danh từ, số từ,... và luôn đi kèm với câu ở dạng phủ định . Nó làm nổi bật từ đứng trước nó, tạo ra một phạm vi để biểu đạt ý phủ định tất cả mọi thứ nằm ngoài phạm vi được đề cập đến bởi từ đó. Cũng giống như trợ từ は、しか thay thế cho trợ từ gốc khi trợ từ gốc đó là を hoặc が và đi kèm theo trợ từ gốc khi đó là các trợ từ khác như ：へ、で、に、 .... しか mang sắc thái phủ định trong khi だけ mang sắc thái khẳng định.', 'ローマ字しか書けません。', 'Tôi viết được mỗi chữ Romaji thôi.', 7),
  (28, 'V1 （thể ます）＋ ながら V2', 'Mẫu này được dùng để biểu thị việc một chủ thể nào đó trong khi tiến hành hành động V2( hành động chính) thì cũng đồng thời thực hiện hành động V1 khác vào cùng thời điểm đó. Cần lưu ý là hành động được biểu thị bởi V1 không được là một hành động có tính chất khoảnh khắc như 起 ( お ) きます、 死 ( し ) にます、たちます、。。。', '音楽を聞食事します。', 'Tôi vừa nghe nhạc vừa ăn cơm.', 1),
  (28, 'Vています', 'Ngoài các cách sử dụng đã được học trong giáo trình I, mẫu V ています này còn được dùng để diễn tả một hành động thường diễn ra như một thói quen của cá nhân nào đó. Khi diễn tả một hành động là thói quen trong quá khứ, thì ta sử dụng mẫu V ていました . Mẫu này thường được dùng chung với các phó từ như : いつも、 毎日 ( まいにち ) 、 毎週 ( まいしゅう ) ,…', '毎朝ジョギングをしています。', 'Tôi chạy bộ mỗi sáng.', 2),
  (28, 'Thể thông thường + し、～', 'Khi các mệnh đề trong câu được trình bày từ cùng một điểm nhìn, ta có thể nối chúng lại với nhau bằng cách sử dụng mẫu này .', 'ワット先生は熱心だし、まじめだし、経験もあります。', 'Thầy Watt vừa nhiệt tình, lại chăm chỉ và có kinh nghiệm.', 3),
  (28, 'それに', 'それに được sử dụng khi bạn muốn diễn tả ý “ hơn nữa”, “ thêm nữa”.', 'どうして名古屋大学を選んだんですか。', 'Tại sao bạn lại chọn trường đại học Nagoya.', 4),
  (28, 'それで', 'それで là liên từ được sử dụng để biểu thị rằng cái được đề cập đến trước đó là nguyên nhân hoặc lý do của mệnh đề theo sau nó.', 'このレストランは値段も安いし、おいしいんです。', 'Nhà hàng này v ừa rẻ lại vừa ngon.', 5),
  (28, 'よく この 喫茶店 に 来るんですか。', 'Trong câu trên (xem thêm phần luyện tập C2, trợ từ - dùng để diễn tả đích đến - được dùng thay cho trợ từ - dùng để diễn tả hướng đi. Các động từ như 行きます、帰ります、来ます có thể sử dụng với cả 2 cách là “ Địa điểm へ ” và “ Địa điểm に ”。 Luyện tập', NULL, NULL, 6),
  (29, 'Vています', 'V ています diễn tả một trạng thái là kết quả của hành động được biểu thị bởi động từ V.', 'NがVています:窓が割れています。', 'Cửa sổ bị vỡ.', 1),
  (29, 'Vて しまいました / しまいます', 'Mẫu câu V てしまいました dùng để nhấn mạnh một hành động hay một sự kiện đã được hoàn tất.', 'ハイさんが持って来たワインは全部飲んでしまいました。', 'Tôi đã uống hết tất cả số rượu mà anh Hải đem tới rồi.', 2),
  (29, 'Vてしまいました', 'Mẫu này dùng để diễn tả cảm giác nuối tiếc của người nói về một việc gì đó xảy ra không thể nào cứu vãn được.', 'パスポートをなくしてしまいました。', 'Tôi làm mất hộ chiếu mất rồi.', 3),
  (29, 'ありました', 'Trong các bài trước, các bạn đã được học あります dùng để chỉ sự tồn tại của một vật nào đó. Tuy vậy, ありました còn có thể được sử dụng với nghĩa là người nói đã tìm thấy cái gì đó ( mà ở đây là chiếc cặp) chứ không phải chỉ được sử dụng để chỉ sự tồn tại của một vật nào đó trong quá khứ.', '前にはここにフォーの店がありました。', 'Trước kia ở đây có một cửa hàng phở.', 4),
  (29, 'どこかで / どこかに', 'Trong bài 13, các bạn đã được học rằng trợ từ へ trong どこかへ và を trong なにかを có thể được giản lược. Tuy vậy, trợ từ で trong どこかで và に trong どこかに thì không được giản lược mà phải giữ nguyên.', 'どこかで財布をなくしてしまいました。', 'Tôi đã làm mất tiêu chiếc ví ở đâu đó rồi.', 5),
  (30, 'V (他動詞）てあります', 'Mẫu này dùng để diễn tả một trạng thái là sự tiếp diễn của kết quả của một hành động do con người cố ý sắp đặt vì một mục đích nào đó. Động từ được sử dụng trong mẫu này là các tha động từ （ 他 ( た ) 動詞 ( どうし ) ） .', 'N1にN2がVてあります：ハイさんの本には、みんなハイさんの名前が書いてあります。', 'Trên tất cả các quyển sách của anh Hải đều ghi tên của anh ấy.', 1),
  (30, 'V (他動詞) ておきます', 'Động từ được sử dụng trong mẫu này là các tha động từ . Mẫu này được dùng với 2 ý nghĩa sau : Biểu thị việc thực hiện một hành vi nhẳm chuẩn bị cho một mục đích nào đó .', '山田君、紙がないから、買っておいてください。', 'Yamada, hết giấy rồi nên cậu mua sẵn đi nhé.( mua giấy để chuẩn bị trước khi nào cần dùng là sẽ có giấy luôn)', 2),
  (30, 'まだ V( thể khẳng định) : Vẫn V', 'まだ trong 2 ví dụ trên có nghĩa là “ vẫn” và dùng để chỉ việc một hành động hoặc 1 trạng thái đang tiếp diễn.', 'まだ雨が降っています。', 'Trời vẫn đang mưa.', 3),
  (30, 'それは～', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', '来月から大阪の本社に転勤なんです。', 'Từ tháng sau tôi sẽ chuyển tới làm việc ở trụ sở chính tại Osaka.', 4),
  (31, 'Thể ý chí （Vよう）', 'Thể hiện tại của động từ có thể chỉ ý muốn của người nói, nhưng để diễn tả một cách tích cực hơn về ý muốn của người nói, ta dùng một thể khác gọi là thể ý chí. Cách tạo thể ý chí như sau : Động từ nhóm I : Thay âm cuối cùng của phần thể ます của động từ ( thuộc hàng い ) bằng âm tương ứng ở hàng お sau đó thêm う vào sau cùng :', 'かえ-ます→かえ-ようみ-ます→みようおぼえ-ます→おぼえ-ようおき-ます→おきよう', 'Động từ nhóm III :', 1),
  (31, 'Cách sử dụng thể ý chí', 'Trong các câu văn ở thể thông thường : Thể ý chí được sử dụng thay cho ~ ましょう trong các câu văn ở thể thông thường :', 'ちょっとやすみませんか。', 'Chúng ta nghỉ một chút đi.', 2),
  (31, '(Vる / Vない) つもりです', 'V るつもり được dùng để diễn tả kế hoạch, dự định của người nói sẽ làm một việc gì đó, còn V ないつもり được dùng để diễn tả dự định của người nói về việc sẽ không làm một việc gì đó.', '国へ帰っても、柔道を続けるつもりです。', 'Dù về nước tôi định vẫn sẽ tiếp tục tập Judo.', 3),
  (31, '[Động từ ở thể từ điển / N の] 予定です', '予定 ( よてい ) có nghĩa là dự định, dự kiến. Nội dung của 予定 ( よてい ) được biểu thị bằng động từ hoặc danh từ đứng trước nó. Vì mẫu câu này nói về một sự việc sẽ tiến hành trong tương lai, nên thì của mệnh đề bổ nghĩa cho 予定 ( よてい ) phải ở thì hiện tại. Khác với 2 mẫu cũng nói về dự định ở trên là ～つもりです＆ V ようとおもいます , chủ từ của mệnh đề bổ nghĩa có thể là người nói (ví dụ 1), người thứ 3 (ví dụ 3) hoặc một sự vật, sự việc nào đó (ví dụ 2).', '私は8月の終わりに国へ帰る予定です。', 'Tôi dự định sẽ về nước vào cuối tháng 8.', 4),
  (31, 'まだ Vて いません', 'Mẫu này chỉ một động tác chưa được hoàn tất hoặc một sự việc chưa xảy ra :', '銀行はまだ開いていません。', 'Ngân hàng vẫn chưa mở cửa.', 5),
  (31, 'こ～ / そ～', 'Trong văn viết, những từ chỉ vật thuộc nhóm そ（それ、その、 .. ） thường được dùng khi muốn nhắc lại những từ hoăc những mệnh đề đã được đề cập đến trước đó. Tuy vậy, đôi khi, người ta có thể dùng thay thế bằng các từ chỉ vật thuộc nhóm こ（これ、この ,.. ） . Trong trường hợp này, người nói muốn miêu tả cho người đọc một thứ gì đó như thể nó thực sự tồn tại, hiện hữu ở trước mắt họ.', '東京にいない物がひとつだけある。それはうつくしい自然だ。', 'Chỉ có một thứ không có ở Tokyo. Đó là thiên nhiên tươi đẹp.', 6),
  (32, '[Vた/ Vない] ほうが いいです', 'Mẫu này được dùng khi muốn đưa ra lời khuyên hoặc lời cảnh báo mạnh mẽ. Khi dùng mẫu này, người nói hàm ý rằng nếu người nghe làm điều ngược lại thì sẽ dẫn đến một kết quả không hay. Vì thế, tùy vào từng tình huống mà mẫu này có thể tạo cho người nghe ấn tượng là bạn đang áp đặt suy nghĩ của mình cho họ nên cần xét đoán tình huống cho thật kĩ trước khi sử dụng.', '毎日運動したほうがいいです。', 'Bạn nên tập thể dục hàng ngày.', 1),
  (32, '([V / い-adj / な-adj / N] Thể thông thường) + でしょう', 'Thể văn thông thường của mẫu này là 「～だろう」 Mẫu này được sử dụng để biểu đạt sự phỏng đoán của người nói từ những thông tin mà họ biết. Khi người nói sử dụng mẫu này dưới dạng câu hỏi giống như ở ví dụ 2, thì có nghĩa là họ đang muốn hỏi xem người nghe phỏng đoán thế nào về sự việc đó. Mẫu này thường được sử dụng kèm với các phó từ như 「たぶん」、「おそらく」 .', '明日は雨が降るでしょう。', 'Có lẽ ngày mai trời mưa.', 2),
  (32, '([V / い-adj / な-adj / N] Thể thông thường) + かも しれません', '～かも しれません cũng là một mẫu câu dùng để thể hiện sự phỏng đoán của người nói, nó có nghĩa rằng có khả năng một sự việc nào đó đã đang hoặc sẽ xảy ra. Mức độ xác thực của phỏng đoán khi dùng mẫu này thấp hơn so với khi dùng mẫu ～でしょう (khoảng 50%)', '約束の時間に間に合わないかもしれません。', 'Có thể chúng ta sẽ không kịp giờ hẹn.', 3),
  (32, 'きっと/たぶん/もしかしたら', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'ハイさんは1日6時間も勉強したんだから、きっと合格しますよ。', 'Anh Hải học 1 ngày những 6 tiếng đồng hồ nên chắc chắc là sẽ thi đỗ..', 4),
  (32, 'Từ để hỏi + か + Tính từ + N', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', '何心配しんぱいなことがあるんですか。', 'Anh có việc gì lo lắng không?', 5),
  (32, 'Từ chỉ số lượng ＋ で', 'Trợ từ で được thêm vào sau các từ chỉ số lượng để biểu thị giới hạn tối đa của giá cả, thời gian, số lượng,… cần thiết để một hành động, một sự kiện hoặc một tình huống nào đó có thể được thực hiện.', '駅まで30分で行けますか。', 'Tôi có thể đi đến nhà ga trong vòng 30p được không?', 6),
  (33, 'Thể mệnh lệnh và thể cấm đoán', 'Cách tạo thể mệnh lệnh : Nhóm I : Đổi âm cuối của phần thể ます thành các âm tương ứng ở hàng え：', 'さげ-ます→さげろみ-ます→みろで-ます→でろおり-ます→おりろ', 'Nhóm III : Thể mệnh lệnh của します là しろ và きます là こい：', 1),
  (33, 'Cách sử dụng thể mệnh lệnh và thể cấm đoán', 'Thể mệnh lệnh được sử dụng để ra lệnh cho ai làm điều gì đó, trong khi thể cấm đoán được sử dụng để cấm ai làm một điều gì đó. Cả 2 thể mệnh lệnh và cấm đoán đều có tính ép buộc cao , vì thế nên việc sử dụng chúng một cách đơn độc hoăc đặt chúng ở sau câu mệnh lệnh là rất giới hạn. Ngoài ra, hầu hết các trường hợp sử dụng thể mệnh lệnh và cấm đoán trong hội thoại chỉ giới hạn ở phái nam. Cả 2 thể mệnh lệnh và thể thông thường được sử dụng đơn độc hoặc được đặt ở cuối câu trong những trường hợp sau đây: Khi người trên ( tuổi tác hoặc địa vị) là phái nam nói với người dưới hoặc khi người bố sai bảo hoặc cấm đoán con chuyện gì đó:', '早く寝ろ。', 'Ngủ sớm đi.', 2),
  (33, '～と 読みます và ～と 書いて あります', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'あの漢字は何と読むんですか。', 'Chữ Hán đó đọc là gì?', 3),
  (33, 'X は Y という 意味です。', 'Mẫu này được sử dụng để làm rõ nghĩa của từ được biểu thị bởi “ X”. Cụm từ という là bắt nguồn từ といいます . Từ để hỏi どういう được sử dụng để hỏi ý nghĩa của một từ/ cụm từ:', '「立入禁止」は入るなという意味です。', '“Tachiiri Kinshi” có nghĩa là cấm vào.', 4),
  (33, '(Thể văn thông thường / “Câu nói”) + と 言(い)って いました', '～と 言 ( い ) いました được sử dụng để trích dẫn lời nói của một người thứ 3( bài 21), trong khi ～と 言って いました được sử dụng để truyền đạt lời nhắn của người thứ 3 :', '田中さんは「明日休みます」と言っていました。', 'Anh Tanaka nhắn là “ Mai tôi nghỉ”.', 5),
  (33, '(“Câu nói” / Thể văn thông thường) + と 伝(つた)えて いただけませんか', 'Mẫu này được sử dụng khi bạn muốn nhờ ai đó truyền tải lời nhắn giúp mình một cách lịch sự.', 'ハイさんに「後で電話をください」と伝えていただけませんか。', 'Anh có thể nhắn anh Hải hãy gọi điện cho tôi sau được không?', 6),
  (34, '(V1た / Nの) あとで、V2', 'Mẫu này dùng để diễn tả việc hành động hay sự việc được biểu thị bởi V2 xảy ra sau khi hành động hay sự kiện được biểu thị bởi V1 hoặc N đã kết thúc.', 'テストを出した後で、答えを思い出しました。', 'Tôi nh ớ ra câu trả lời sau khi đã nộp bài kiểm tra.', 1),
  (34, '(V1( thể て) / V1( thể ない) ないで) + V2', 'V1 là một hành động hay trạng thái đính kèm với hành động chính được biểu thị bởi động từ V2. Mệnh đề 1 ( có V1) giải thích cho người nghe biết mệnh đề 2 tiến hành như thế nào . Chủ thể của V1 và V2 là một. Ý nghĩa của V1 て V2 ở đây khác với V1 て V2 dùng để liệt kê những hành động xảy ra liên tiếp nhau mà ta đã học ở trong các bài trước.', 'Aはベトナム人です。Bは日本人です。AとBは料理の食べ方について話しています。さしみはどうやって食べますか。', 'Sashimi thì ăn như thế nào?', 2),
  (34, 'V1 (thể ない) ないで、V2', 'Mẫu trên biểu thị việc một người nào đó sẽ không làm hành động V1, thay vào đó sẽ tiến hành hành động V2. Thì của câu được quyết định bởi thì của động từ V2.', '最近バスやタクシーに乗らないで、よく歩いています。', 'Gần đây tôi không đi xe bus hay xe taxi mà( thay vào đó) thường đi bộ.', 3),
  (35, 'Thể điều kiện （～ば）', 'Cách chuyển động từ sang thể điều kiện như sau : Động từ : Nhóm I : Chuyển âm cuối của phần thể ます sang âm tương ứng ở hàng え sau đó thêm ば.', 'ききます→きけばふります→ふればいそぎます→いそげばおもいます→おもえばのみます→のめばまちます→まてばよびます→よべばだします→だせば', 'Nhóm II: Thêm れば vào cuối phần thể ます.', 1),
  (35, 'A ば B', 'Bằng cách sử dụng thể điều kiện, mệnh đề trước của câu （ A ） biểu thị điều kiện cần thiết để một sự kiện hoặc một sự việc nào đó xảy ra (mệnh đề phụ). Biểu thị điều kiện cần thiết để một sự việc nào đó xảy ra (A là điều kiện của B):', '朝になれば、太陽が昇ります。', 'Nếu trời sáng thì mặt trời sẽ lên.', 2),
  (35, 'N なら、～', 'N なら được sử dụng khi người nói tiếp nhận một chủ đề được đưa ra bởi một người khác và đưa ra một số thông tin liên quan đến chủ đề đó. Mẫu này được sử dụng trong văn cảnh khi muốn đưa ra lời khuyên cho người khác liên quan đến chủ đề họ vừa đưa ra:', '温泉に行きたいんですが、どこかいい所ありませんか。', 'Tôi muốn đi suối nước nóng, có chỗ nào hay không?', 3),
  (35, 'Từ để hỏi + thể điều kiện + いいですか`', 'Mẫu này được dùng khi người nói muốn hỏi xin lời khuyên hoặc chỉ thị của người nghe về cách tốt nhất để thực hiện một việc gì đó. Cách sử dụng của mẫu này giống với ～たら いいですか mà các bạn đã học trong bài 26. Vì vậy, bạn có thể dùng 2 cách nói này để thay thế cho nhau như trong 2 ví dụ dưới đây:', '本を借りたいんですが、どうすればいいですか。', 'Tôi muốn mượn sách thì phải làm thế nào?', 4),
  (35, '(Tính từ đuôi い / な thể điều kiện) + (động từ nguyên dạng, tính từ đuôi い, tính từ đuôi な) + ほど', 'Cùng một động từ/ tính từ được sử dụng 2 lần : trước ば / なら và ほど trong cùng một câu nhằm biểu thị việc mức độ được diễn tả ở mệnh đề sau của câu tăng lên/giảm đi theo sự thay đổi của mức độ được diễn tả ở mệnh đề trước của câu.', 'ビートルズの音楽は聞けば聞くほど好きになります。', 'Nhạc của Beatles càng nghe càng thích.', 5),
  (36, '[V1 (nguyên dạng) / V1 (thể ない)] + ように、V2', 'Động từ V1 biểu thị một trạng thái là mục đích hoặc mục tiêu. Động từ V2 thì biểu thị một hành động có ý chí nhằm tới gần mục đích, mục tiêu đó', '速く泳げるように、毎日練習しています。', 'Mục tiêu Hành động có ý chí', 1),
  (36, '[V ( thể từ điển) ように / V ( thể ない ) なく] + なります', 'なります biểu thị việc một trạng thái này biến đổi thành một trạng thái khác. Động từ V được sử dụng ở đây là những động từ biểu thị một khả năng, năng lực nào đó, nên : Động từ V ở mẫu trên là các động từ ở thể khả năng, Hoặc các động từ biểu thị năng lực như: わかります、 見 ( み ) えます、 聞 ( き ) こえます ,… Và khi sử dụng mẫu này, các động từ đó phải chuyển sang thể từ điển / thể ない ( nếu là động từ ở thể khả năng thì chuyển về thể từ điển / thể ない của thể khả năng đó : 読 ( よ ) める、 話 ( はな ) せる、 着 ( き ) られる、 読 ( よ ) めない、 話 ( はな ) せない、 着 ( き ) られない …) V (thể từ điển) ように なります diễn tả sự biến đổi từ trạng thái không làm được điều gì đó sang có thể làm được điều đó.', '毎日練習すれば、泳げるようになります。', 'Nếu luyện tập hàng ngày thì bạn sẽ bơi được', 2),
  (36, '[V (thể từ điển) / V (thể từ điển)] ように します', 'Mẫu này đươc sử dụng để diễn tả việc một người nào đó thường xuyên hoặc liên tục nỗ lực để làm một việc gì đó ( hoặc nỗ lực để không làm một việc gì đó).', '～ようにしています：', 'Mẫu này diễn tả việc một người nào đó thường xuyên và liên tục cố gắng làm một việc gì đó vì một mục đích nhất định:', 3),
  (36, 'とか', '～とか được sử dụng để đưa ra các ví dụ giống như や , nhưng とか mang tính hội thoại hàng ngày hơn. Không giống như や、 đôi lúc とか có thể đứng sau danh từ cuối cùng để ngầm đưa ra một số các ví dụ khác tương tự.', 'どんなスポーツをしていますか。', 'Bạn đang chơi môn thể thao nào?', 4),
  (37, 'Động từ ở dạng bị động', 'Cách tạo động từ ở dạng bị động: Nhóm I: Những động từ trong nhóm này luôn có âm cuối ở phần thể ます là những âm thuộc hàng い . Để tạo dạng bị động của động từ, ta thay âm cuối ở phần thể ます thành âm tương ứng ở hàng あ rồi thêm れ vào sau đó.', 'かき・ます→かかれ・ますとり・ます→とられ・ますふみ・ます→ふまれ・ますいい・ます→いわれ・ますよび・ます→よばれ・ますまち・ます→またれ・ます', 'Nhóm II: Để tạo dạng bị động của động từ nhóm II, ta thêm られ vào sau phần thể ます của động từ.', 1),
  (37, 'N1 (người thứ 1) は N2 (người thứ 2) に V (động từ ở dạng bị động)', 'Khi hành động của một người ( người thứ 2 - người thực hiện hành động V ) tác động tới một người khác ( người thứ 1- người chịu tác động của V ) thì người người thứ 1 có thể diễn tả hành động đó từ phía của mình bằng cách sử dụng mẫu câu này. Trong trường hợp đó, người thứ 1 (người chịu tác động của hành động- N1) sẽ trở thành chủ đề của câu, còn người thứ 2 (người chịu tác động của hành động- N2) sẽ được biểu thị bằng trợ từ に và động từ V được chuyển sang dạng bị động.', '先生は私を叱しかりました。', 'N1 N2 V', 2),
  (37, 'N1 (người thứ 1) は N2 (người thứ 2) に N3 (thuộc sở hữu hoặc là 1 bộ phận của N1) を V (dạng bị động)', 'Khi hành động của 1 người( người thứ 2-N1) tác động trực tiếp tới một đối tượng thuộc sở hữu hoặc là 1 bộ phận của người khác (người thứ 1 - N1) và gây ra cho người đó một sự phiền phức hay khó chịu nào đó thì người đó ( người thứ 1 - N1) sẽ sử dụng mẫu này để nói lên cảm giác của mình.', '弟が私のパソコンを壊しました。', '<v:shapetype', 3),
  (37, 'N (Vật) が / は V(thể bị động)', 'Khi không cần đề cập đến người đã thực hiện hành động được biểu thị bởi động từ V mà chỉ muốn đề cập đến đối tượng của hành động đó, bạn có thể đưa đối tượng của động từ đó lên làm chủ đề của câu. Trong trường hợp này, ta sẽ sử dụng động từ ở dạng bị động như sau:', 'フランスで昔の日本の絵が発見されました。', 'Bức tranh cổ của Nhật đã được phát hiện thấy tại Pháp.', 4),
  (37, 'N1 は N2 (người) によって V (dạng bị động)', 'Khi một vật gì đó( N1) được tạo ra hoặc được khám phá ra thì nó sẽ được miêu tả bằng một động từ ở dạng bị động, còn người khám phá ra hoặc tạo ra nó( N2) sẽ được biểu thị bằng cụm từ によって thay cho に như trong các câu bị động thông thường khác. Các động từ như: かきます、はつめいします、はっけんします ,...... thường được sử dụng trong mẫu câu trên.', '「源氏物語」は紫式部によって書かれました。', 'Truyện Genjimonogatari được viết bởi Murasaki shikibu', 5),
  (37, 'N から / Nで つくります', 'Khi một vật nào đó được làm từ một nguyên liệu gốc nào đó( phải qua nhiều bước chế biến mới thành và bằng mắt thường không thể thấy được ) thì nguyên liệu đó được biểu thị bằng trợ từ から . Còn khi một vật được làm từ một nguyên liệu đặc định nào đó, có thể thấy rõ được bằng mắt thường thì nguyên liệu đó được biểu thị bằng trợ từ で 。', 'ビールは麦から造られます。', 'Bia được làm từ lúa mạch.', 6),
  (38, 'V (thể thông thường) の', 'Thêm tr ợ từ の vào sau câu văn ở thể thông thường thì có thể danh từ hóa cụm từ đó.', NULL, NULL, 1),
  (38, 'V (thể từ điển) のは + tính từ + です', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'テニスはとても面白いです。', 'Tennis rất thú vị.', 2),
  (38, 'V (thể từ điển) のが + tính từ + です', 'Các tính từ được sử dụng trong các mẫu này thường diễn tả một ý thích ( thích hoặc không thích), một kĩ năng hoặc một năng lực nào đó, ví dụ như : 好 ( す ) き、 嫌 ( きら ) い、 上手 ( じょうず ) 、 下手 ( した ) 、 速 ( はや ) い、 遅 ( おそ ) い ,....', '私は花が好きです。', 'Tôi thích hoa.', 3),
  (38, 'V (thể từ điển) の を 忘(わす)れました。', 'Mẫu này diễn tả việc một người nào đó đáng lẽ ra phải thực hiện hành động V nhưng đã quên thực hiện hành động đó.', 'かぎを忘れました。', 'Tôi quên chìa khóa.', 4),
  (39, 'Động từ / tính từ / danh từ + て/で,~', '* Động từ Khẳng định : động từ thể て ,~ Phủ định : Động từ thể ない なくて ,~ *Tính từ Tính từ đuôi い : Bỏ [ い ] th ê m [ くて ] Tính từ đuôi な : Bỏ [ な ] th ê m [ で ] *Danh từ : Thêm [ で ] Trong mẫu này, mệnh đề trước của câu biểu thị nguyên nhân và mệnh đề sau biểu thị kết quả xảy ra bởi nguyên nhân đó. Không giống như, ～から mẫu câu này có nhiều hạn chế trong cách sử dụng. Mệnh đề sau của câu không được chứa các từ thể hiện ý chí của người nói à các từ được sử dụng ở mệnh đề sau của câu được giới hạn ở 3 trường hợp sau đây: Các động từ và tính từ biểu hiện cảm xúc như : びっくりする、 安心 ( あんしん ) する、 困 ( こま ) る、さびしい、うれしい、 残念 ( ざんねん ) だ、 ….', 'ニュースを聞いて、びっくりしました。', 'Nghe tin đó tôi ngạc nhiên.', 1),
  (39, 'Danh từ + で', 'Trợ từ で trong mẫu này được sử dụng để chỉ nguyên nhân. Danh từ N được sử dụng ở đây là những danh từ diễn tả một sự vật, sự việc có khả năng gây ra một kết quả gì đó như : các danh từ miêu tả về hiện tượng tự nhiên, miêu tả một sự kiện,.. ： 地震 ( じしん ) (động đất) 、 火事 ( かじ ) (hỏa hoạn) 、 事故 ( じこ ) (tai nạn),…. Cũng như mẫu câu 1 ở trên, không được sử dụng mẫu câu này khi mệnh đề sau で thể hiện ý chí của người nói.', '地震でビルが倒たおれました。', 'Tòa nhà bị đổ bởi động đất.', 2),
  (39, 'Thể thông thường + ので,…', 'Cũng giống như ～から mà chúng ta đã học ở bài 9 、～ので cũng được dùng để chỉ nguyên nhân, lý do. Trong khi ～から nhấn mạnh một cách chủ quan nguyên nhân thì ～ので lại trình bày một cách khách quan về mối liên hệ giữa nguyên nhân và kết quả như là một diễn biến tự nhiên. Vì thế, sử dụng ～ので giúp làm mềm quan điểm của người nói , khiến người nghe không có cảm giác bị áp đặt. ～ので thường được dùng khi muốn trình bày một cách nhẹ nhàng về lý do khi muốn xin phép hoặc đưa ra lời giải thích .', '日本語がわからないので、英語で話していただけませんか。', 'Vì tôi không hiểu tiếng Nhật nên bạn có thể nói bằng tiếng Anh được không?', 3),
  (39, '[Nの / V (thể từ điển)] + 途中(とちゅう)で', '途中 ( とちゅう ) で có nghĩa là “ giữa lúc”, “ trên đường”.', '実は来る途中で事故があって、バスが遅れてしまったんです。', 'Thật ra là trên đường tới đây thì có vụ tai nạn, nên xe buýt đã bị chậm trễ.', 4),
  (40, 'Từ để hỏi, Tính từ đuôi な , Thể thông thường', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'JL107便は何時に到着とうちゃくしますか。調しらべてください。', 'Chuyến bay số hiệu JL107 hạ cánh lúc mấy giờ ? Hãy tra xem.', 1),
  (40, 'Tính từ đuôiい, Tính từ đuôi な', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', '忘年会に出席しゅっせきしますか。出席しゅっせきしませんか。２０日までに返事をください。', 'Bạn có tham gia buổi tiệc cuối năm không?( Hay là) bạn không tham gia. Hãy cho tôi câu trả lời trước ngày 20.', 2),
  (40, '4, V（ thểて）+ みます', 'Mẫu này được sử dụng để diễn tả việc hành động được biểu thị bởi động từ V được tiến hành thử để xem kết quả sẽ ra sao.', 'もう一度考えてみます。', 'Tôi sẽ thử suy nghĩ lại 1 lần nữa.', 3),
  (40, '5, Tính từ đuôi い (～い ) ～さ', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', 'たかいたかさ', 'Chiều cao', 4),
  (41, 'Các cách diễn đạt về việc cho và nhận', 'Trong bài 7 và bài 24, chũng ta đã học về những cách diễn đạt việc cho và nhận một vật hoặc một hành động nào đó. Trong bài này, bạn sẽ học thêm những cách diễn đạt khác về việc cho và nhận một vật hay một hành động nào đó nhưng các cách diễn đạt này còn thể hiện cả mối quan hệ giữa người cho và người nhận ,', '私は息子にお菓子かしをやりました。（あげました）', 'Tôi cho con trai tôi bánh.', 1),
  (41, 'Cho và nhận hành động', 'やります、いただきます và くださいます còn được sử dụng khi muốn diễn tả việc cho và nhận hành động.', 'a)V(thểて)やります私は息子に紙飛行機を作ってやりました（あげました）。', 'Tôi gấp cho con trai tôi máy bay giấy.', 2),
  (41, 'V（thểて）くださいませんか', '～てくださいませんか là cách diễn đạt một cách lịch sự yêu cầu, đề nghị nào đó, mặc dù nó không lịch sự bằng mẫu ～て いただけませんか mà ta đã học trong bài 26.', 'コピー機きの使い方を教えてくださいませんか。', 'Bạn có thể dạy tôi cách sử dụng máy photo được không?', 3),
  (41, 'N に V', 'Trợ từ に ở đây mang ý nghĩa : “ làm quà kỉ niệm ”, “ kỉ niệm cho”', '田中たなかさんが結婚けっこんの祝いわいにこのお皿をくださいました。', 'Anh Tanaka tặng tôi chiếc đĩa này làm quà cưới.', 4),
  (42, 'V ( thể từ điển )', 'Mẫu này được sử dụng để diễn tả mục đích của một hành động nào đó.', '車を買うために、貯金ちょきんしています。', 'Tôi đang tiết kiệm tiền để mua ôtô.', 1),
  (42, 'V ( thể từ điển )', 'Như các bạn đã học trong bài 38, V( thể từ điển) の có thể được sử dụng như một cụm danh từ. V( thể từ điển) の に và N に được sử dụng kèm với các từ : 使 つか う ( dùng) 、いい (tốt) 、 便利 べんり だ (tiện) 、 役 やく に 立 た つ ( có ích) 、（ 時間 じかん が）かかる (tốn ),… để chỉ một mục đích của một động từ hay một tính từ nào đó ở đằng sau.', 'このはさみは花を切るのに使います。', 'Cái kèo này được dùng để cắt hoa. ( dùng cho mục đích cắt hoa).', 2),
  (42, 'Số từ + は', 'Khi thêm trợ từ は vào sau một số từ ( từ chỉ số lượng) thì nó sẽ biểu thị giá trị nhỏ nhất mà người nói dự tính là cần thiết để làm gì.', '日本では結婚式をするのに200万円は要いります。', 'Ở Nhật để làm đám cưới thì cần có ít nhất là 2 triệu Yên.', 3),
  (42, 'Số từ + も', 'Khi thêm trợ từ も vào sau một số từ( từ chỉ số lượng) thì nó sẽ biểu thị việc người nói nghĩ rằng giá trị được biểu thị bởi số từ đó quá nhiều .', '駅まで行くのに2時間もかかりました。', 'Mất những 2 tiếng đồng hồ để đi tới ga.', 4),
  (43, 'V( thểます) Tính từ đuôi い, な', 'Khi tình hình hiện tại khiến cho người nói phỏng định về một sự việc nào đó, người nói sẽ dùng mẫu này để biểu thị tình hình đó. Các phó từ như : いまにも、もうすぐ、これから 、 được thêm vào đằng sau để chỉ rõ hơn về thời điểm mà người nói nghĩ rằng sự việc đó sẽ xảy ra:', '今にも雨が降りそうです。', 'Trời như sắp mưa đến nơi.', 1),
  (43, 'Đặc biệt: いい --> よさそう', 'Được sử dụng để diễn tả nhận định bằng cách nhìn quan sát bên ngoài sự vật, hiện tượng chứ không phải bằng cách xác nhận trực tiếp.', 'ハイさんが作った料理はおいしそうです。', 'Món anh Hải nấu trông có vẻ ngon.', 2),
  (43, 'V ( thể て ) きます', 'Trong tiếng Nhật thường có cấu trúc động từ bổ nghĩa dưới dạng: ĐỘNG TỪ CHÍNH + ĐỘNG TỪ BỔ NGHĨA Chúng ta đã học một loạt các cấu trúc kiểu này như : V てみる、 V てくれる、 V ている、 ….Cấu trúc V てきます cũng là một trong những cấu trúc động từ bổ nghĩa đó. V てきます có nghĩa là : “ đi đâu đó để làm gì rồi quay trở lại', 'ちょっとたばこを買ってきます。', 'Tôi đi mua thuốc lá một chút ( rồi sẽ về).', 3),
  (44, 'V（ます）/ Tính từ đuôi い, な', '～すぎます đ ược sử dụng để biểu thị việc mức độ của một hành động hay một trạng thái nào đó vượt quá mức cần thiết . Vì vậy, nó thường được dùng trong những trường hợp mà người nói cho rằng đáng lẽ ra không nên làm như vậy hoặc trong tình trạng không vừa ý.', 'ゆうべお酒を飲み過ぎました。今頭が痛いたいです。', 'Tối qua tôi đã uống quá nhiều rượu. Bây giờ đầu tôi đau.', 1),
  (44, 'V ( thể ます) / やすいです / にくいです', 'Dùng để biểu thị mức độ khó hay dễ trong việc thực hiện, tiến hành một việc gì đó:', 'このパソコンは使いやすいです。', 'Cái máy tính này dễ sử dụng.', 2),
  (44, 'Tính từ đuôi な（～な） → ～に / します N に', 'Nếu như mẫu câu ～く / ～になります mà bạn đã học trong bài 19 diễn tả việc một vật hay một sự việc nào đó biến đổi sang một trạng thái nào đó, thì mẫu ～く / ～にします lại miêu tả việc một người nào đó làm cho một vật chuyển sang một trạng thái nào đó.', 'ラジオの音を大きくします。', 'Vặn to tiếng radio lên.', 3),
  (44, 'Tính từ đuôi な（～な） →に', 'Khi chuyển tính từ sang dạng như ở trên thì chúng sẽ có chức năng như một trạng từ.', 'ハイさんは親切しんせつに道を教えてくれまし。', 'Anh Hải chỉ đường cho tôi một cách nhiệt tình.', 4),
  (45, 'Thể thông thường / Tính từ đuôiな + な', '～ 場合 ばあい は là mẫu câu được sử dụng để nói về một tình huống giả định nào đó . Mệnh đề trước ～ 場合 ばあい は đưa ra một tình huống giả định, còn mệnh đề sau nó thì chỉ ra cách xử lý khi tình huống đó xảy ra ～ . 場合 ばあい は có thể theo sau cả danh từ, tính từ và động từ. Do 場合 ばあい là một danh từ nên các động từ, danh từ hay tính từ khi đứng trước đều được chia theo các nguyên tắc giống như khi đứng trước các danh từ khác trong mệnh đề trạng ngữ mà ta đã học. Khác với ～ば、～と thường có một số giới hạn về các từ xuất hiện ở mệnh đề sau, mệnh đề sau ～ 場合 ばあい は không bị giới hạn gì.', '会議に間に合わない場合ばあいは、連絡れんらくしてください。', 'Hãy liên lạc trong trường hợp không đến kịp buổi họp.', 1),
  (45, 'V い ( な ) -adj thể thông thường', 'のに có thể theo sau cả danh từ, động từ và tính từ. Mẫu trên được sử dụng khi sự việc xảy ra ở mệnh đề 2( mệnh đề sau のに ) trái ngược với những gì mà người nói dự tính từ mệnh đề 1( mệnh đề trước のに ) , làm cho người nói cảm thấy ngạc nhiên, bất mãn . Người nói sử dụng mẫu này để truyền đạt cảm giác bức xúc, khó chịu, ngạc nhiên ,.. của mình tới người nghe.', '約束をしたのに、彼女は来ませんでした。', 'Cô ấy đã hẹn mà lại không đến.', 2),
  (46, 'Vる/ Vている/ Vた', 'T ừ ところ có nghĩa gốc là “ chỗ”, “ địa điểm” , nhưng nó cũng được dùng để chỉ một vị trí mang tính thời gian. ところ mà bạn học trong bài này mang ý nghĩa thứ 2, nó được đặt ở phần sau của câu để truyền đạt đến người nghe tiến độ của một hành động nào đó. Mẫu này chỉ được dùng với những động từ mà thời điểm sắp bắt đầu, thời điểm đang thực hiện và thời điểm hoành thành hành động được phân định một cách rõ ràng. Còn những động từ có tính trạng thái thì không dùng ( 例： 住 す む )', '昼ごはんはもう食べましたか。', 'Bạn đã ăn trưa chưa?', 1),
  (46, 'Vたばかりです', 'Mẫu này biểu thị việc một hành động hoặc một sự kiện nào đó vừa mới xảy ra không bao lâu . Đây là cách diễn đạt cảm nhận của người nói về thời gian, nên nó có thể được sử dụng với cả những hành động đã được hoàn tất khá lâu nến như người nói cảm thấy nó vẫn còn ngắn . Đây chính là điểm khác nhau giữa mẫu này và mẫu V たところです . V たところです thường chỉ biểu hiện được những hành động vừa mới hoàn tất xong tức thì. Các phó từ được sử dụng chung với không chỉ giới hạn bởi các từ biểu hiện thời gian mới vừa ngay trước đó như : さっき、今 mà còn có thể dùng kèm với những từ biểu hiện thời gian khá dài như : 2 時間前 じかんまえ 、 昨日 きのう 、 先週 せんしゅう 、 先月 せんげつ ,…', '例1：さっき昼ごはんを食べたばかりです。', 'Tôi vừa ăn trưa xong.', 2),
  (46, 'Tính từ đuôi な ＋', 'Mẫu này được sử dụng khi người nói muốn thể hiện rằng mình cảm thấy khá chắc chắn về những điều được nói đến ở phần câu đứng trước ～はずです . Bằng cách sử dụng mẫu này, người nói hàm ý rằng mình có cơ sở chắc chắn , một lý do khách quan để nhận định như vậy, và mình khá chắc chắn vì điều mà mình nói .', 'ハイさんはきょう来るでしょうか。', 'Hôm nay anh Hải có đến không nhỉ?', 3),
  (47, 'Thể thông thường + そうです: TRUYỀN ĐẠT', 'Cấu trúc này dùng để truyền đạt y nguyên một thông tin mà bạn có được từ một nguồn nào đó và không thêm một chút suy nghĩ cá nhân nào của bạn vào . Khi muốn chỉ ra nguồn của thông tin, bạn đặt chúng ở đầu câu, sau đó thêm vào đằng sau nó cụm từ ～によると', '天気予報よほうによると、明日は寒くなるそうです。', 'Theo dự báo thời tiết thì ngày mai trời sẽ trở lạnh', 1),
  (47, 'な-adj ～だ →～な ようです', '～ようです dùng để biểu thị suy đoán chủ quan của người nói dựa trên việc suy nghĩ và tổng hợp những thông tin mà người đó có được thông qua các giác quan của mình ( nghe thấy, nhìn thấy, đọc thấy, sờ thấy,..). Câu kết thúc bằng ～ようです đôi lúc thường đi kèm với từ どうも nhằm hàm ý rằng người nói có thể không chắc chắn điều mình đang nói có phải là thật không.', '人が大勢集まっていますね。', 'Nhiều người tụ tập thế nhỉ.', 2),
  (47, 'So sánh', 'Để dễ phân biệt, ta thống nhất gọi: Mẫu ～そうです dùng để diễn tả phỏng đoán của bạn dựa trên hiện tượng mà mình tận mắt chứng kiến mà ta đã học ở bài 43 là ～そうです（ TRẠNG THÁI ） Mẫu “ Thể thông thường + そうです ” dùng để truyền đạt nguyên văn một thông tin mình nghe được từ một nguồn nào đó mà ta học trong bài hôm nay là ～そうです（ TRUYỀN ĐẠT ） a. So sánh ～そうです（ TRẠNG THÁI ） và ～ようです : +) ～そうです (TRẠNG THÁI) chỉ được dùng khi người nói tận mắt chứng kiến một sự vật, hiện tượng nào đó và sau đó nói ra hình dung của mình mà không cần phải suy nghĩ, tổng hợp gì. Do hình dung ấy đưa ra dựa trên việc người nói tận mắt chứng kiến, nên thật ra nó thiên về việc miêu tả trạng thái của sự vật, hiện tượng hơn. Vì thế, khi người nói không tận mắt chứng kiến sự vật, hiện tượng thì không dùng mẫu này . + ) ～ようです dùng khi người nói đưa ra một phỏng đoán dựa trên các thông tin có được từ các giác quan của mình ( cảm thấy, sờ thấy, nghe thấy, nhìn thấy,..) và sau đó phải dùng những kinh nghiệm sẵn có, những trải nghiệm của bản thân,.., vận dụng đầu óc để tổng hợp các thông tin đó . Trong những trường hợp mà người nói chỉ nhìn bằng mắt thường, không dùng đầu óc để suy nghĩ, tổng hợp thông tin thì không dùng ～ようです . +) Một điểm khác nhau rõ rệt mà các bạn có thể nhận thấy là ～ようです có thể dùng với các động từ ở dạng V ている、 V た nhằm diễn tả phỏng đoán của người nói về một sự việc đã xảy ra hoặc đang xảy ra, còn ～そうです（ TRẠNG THÁI ） chỉ dùng với các động từ ở thể ます nhằm diễn tả phỏng đoán của người nói về một sự việc sắp xảy ra.', '雨がふりそうです。', 'Trời như sắp mưa ấy nhỉ', 3),
  (47, '．声・音・におい・味/ がします', '(nguồn chưa ghi giải thích — cần bổ sung qua trang quản trị)', '変な音がしますね。', 'Có tiếng động lạ đúng không.', 4),
  (48, 'Động từ dạng sai khiến – (kí hiệu là Vさせます)', 'Cách tạo động từ dạng sai khiến: Nhóm I : Những động từ trong nhóm này luôn có âm cuối phần thể ます là những âm thuộc hàng い . Để tạo dạng sai khiến của động từ, ta thay thế âm đó bằng âm tương ứng ở hàng あ rồi thêm せ vào sau.', 'たべ・ます→たべさせ・ますい・ます→いさせ・ますしらべ・ます→しらべさせ・ます', 'Nhóm III :', 1),
  (48, 'Câu với động từ dạng sai khiến', 'Câu với động từ dạng sai khiến được dùng để biểu thị việc người trên bắt buộc , hoặc cho phép người dưới thực hiện một hành động nào đó. Tùy vào động từ V là tự động từ hay tha động từ mà cấu trúc ngữ pháp của câu nói cũng thay đổi theo như dưới đây. Để tiện cho việc theo dõi, ta quy ước: Người thực hiện hành động V là NGƯỜI 2. Người cho phép hay bắt buộc NGƯỜI 2 thực hiện hành động V là NGƯỜI 1. (Người 1) は / が (Người 2) を V させます ( tự động từ)', '部長は山田さんを大阪へ出張させます。', 'Người 1 người 2 V sai khiến', 2),
  (48, 'Cách sử dụng thể sai khiến', 'Câu văn sai khiến được dùng để biểu thị việc người trên( NGƯỜI 1) bắt buộc hay cho phép người dưới( NGƯỜI 2) làm một hành động nào đó.. Nó được sử dụng khi sự liên hệ trên dưới giữa NGƯỜI 1 và NGƯỜI 2 rõ ràng ( VD: cha con, anh em hay cấp trên với cấp dưới trong cùng 1 công ty,…).', '私は弟に荷物を持たせます。', 'Tôi sẽ bắt em trai tôi mang hành lý.', 3),
  (48, 'Vさせていただけませんか', '～ていただけませんか mà chúng ta đã học trong bài 26 được sử dụng khi mình nhờ người nào đó làm một việc gì. Còn khi muốn xin người nào đó cho phép mình làm hành động V thì sử dụng “ thể て của động từ sai khiến + いただけませんか ”.', 'コピー機の使い方を教えていただけませんか。', 'Anh có thể dạy tôi cách dùng máy photo được không.', 4),
  (49, '敬語 (けいご) (Kính ngữ)', 'Bạn sẽ học về kính ngữ trong 2 bài 49 và 50. Kính ngữ là cách diễn đạt dùng để bày tỏ sự kính trọng, tôn trọng, thái độ lịch sự đối với người nghe hay người được đề cập đến trong câu chuyện. Người nói thể hiện sự kính trọng của mình như thế nào là phụ thuộc vào mối quan hệ của anh ta với người nghe hay người được đề cập đến trong câu chuyện. Nói một cách tóm tắt, thì kính ngữ được sử dụng trong các trường hợp sau đây : Khi nói chuyện với người trên ( thầy giáo, cấp trên, người lớn tuổi,..) Khi nói chuyện với người lạ hoặc chưa thân thiết lắm Khi nói chuyện trong những tình huống trang trọng, lịch sự. Rất nhiều người học tiếng Nhật khi nghe nói đến 敬語 ( けいご ) ( kính ngữ) thì đều nghĩ rằng : “ Kính ngữ = quan hệ trên dưới”. Đó chỉ là cách nhìn phiến diện. Trong tiếng Nhật, việc 2 người lớn có tuổi tác và địa vị xã hội ngang bằng nhau nhưng vẫn dùng kính ngữ khi nói chuyện với nhau là một điều hết sức bình thường. Từ cách họ nói chuyện, chúng ta có thể biết được mức độ thân thiết của họ. Ví dụ, nếu 2 đồng nghiệp ( xấp xỉ tuổi nhau) trong công ty khi nói chuyện với nhau mà dùng kính ngữ, thì có thể hiểu là giữa 2 người vẫn có một khoảng cách nhất định. Còn khi họ nói chuyện với nhau mà không dùng kính ngữ nữa, thì có thể kết luận rằng họ đã bắt đầu trở nên thân tình hơn. Cũng có những trường hợp 2 đồng nghiệp trong giao tiếp hàng ngày không dùng kính ngữ ( vì đã khá thân tình) , nhưng trong cuộc họp của công ty vẫn dùng kính ngữ với nhau. Bởi vì việc dùng hay không dùng kính ngữ không chỉ phụ thuộc vào mối quan hệ của 2 người, mà còn phụ thuộc vào từng tình huống, từng hoàn cảnh . Ngoài ra, khi dùng kính ngữ trong tiếng Nhật cũng phải lưu ý đến khái niệm : うち ( trong nhóm) và そと ( ngoài nhóm) trong văn hóa của người Nhật. うち là những người thuộc cùng một nhóm, một đoàn thể, một tổ chức với mình, còn そと là những người bên ngoài nhóm đó. Khái niệm うち・そと chỉ mang tính tương đối. Ví dụ: Khi nói chuyện với đồng nghiệp trong công ty về người trong gia đình mình, thì những người trong gia đình được coi là うち và đồng nghiệp được coi là そと . Nhưng khi bạn nói chuyện với đối tác của bạn về những người trong công ty mình, thì đổi tác lại trở thành そと và những người trong công ty của bạn lạ trở thành うち . Khi nói chuyện với người ngoài nhóm （そと） về những người trong nhóm của mình （うち） , thì người nói sẽ coi những người trong nhóm đó như chính bản thân anh ta. Chính vì vậy, trong trường hợp 1 người nói với người ngoài nhóm về 1 người trong nhóm của mình ,thì ngay cả khi người trong nhóm là người hơn anh ta về địa vị và tuổi tác, thì anh ta cũng không dùng kính ngữ đối với người được đề cập đến ở đây.', NULL, NULL, 1),
  (49, 'Các loại kính ngữ', '敬語 ( けいご ) (kính ngữ) được chia thành 3 loại chính, đó là: 尊敬語 ( そんけいご ) (tôn kính ngữ) 、 謙譲語 ( けんじょうご ) (khiếm tốn ngữ) 、 và 丁寧語 ( ていねいご ) (từ ngữ lịch sự). Trong bài 49, ta sẽ tìm hiểu về 尊敬語 ( そんけいご ) (tôn kính ngữ).', NULL, NULL, 2),
  (49, '尊敬語(そんけいご) (tôn kính ngữ)', '尊敬語 ( そんけいご ) ( tôn kính ngữ) là cách diễn tả dùng để bày tỏ sự kính trọng khi nói về người nghe hay người được đề cập đến trong câu chuyện và cả những hành động cũng như đồ vật có liên quan đến những người này. ( Còn khi nói về mình hay những hành động do mình làm thì tuyệt đối không sử dụng 尊敬語 ( そんけいご ) ) Động từ : Để chuyển một động từ sang dạng tôn kính ngữ, chúng ta có 3 cách sau : Chuyển động từ sang dạng bị động Động từ ở dạng bị động cũng có thể được sử dụng để bày tỏ sự kính trọng.', '中村さんは7時に来ます。', 'Anh Nakamura sẽ đến lúc 7 giờ.', 3),
  (49, '敬語 (けいご) và thể văn', 'Một câu văn có thể kết thúc với kính ngữ ở thể thông thường. Khi đó câu văn đó cũng sẽ trở thành thể thông thường. Kiểu câu văn này được sử dụng trong trường hợp người nói nói chuyện với một người bạn thân của mình về một người nào đó mà người nói muốn thể hiện sự kính trọng. (VD: Hai đồng nghiệp thân nhau trong công ty nói chuyện về giám đốc của mình, 2 sinh viên chơi thân với nhau nói về thầy giáo,..). Xét 2 trường hợp sau đây :', '社長はもうお帰りになりましたか。社長はもうお帰りになった？', '2 người đang nói chuyện không thân nhau', 4),
  (49, 'Thống nhất mức độ kính ngữ trong câu văn', 'Khi biểu hiện sự kính trọng đối với người nghe (hoặc người đọc) thì không phải chỉ thay đổi một số từ trong câu văn mà toàn thể câu văn đó phải thống nhất tiêu chuẩn 敬語 ( けいご ) .', '家族のみんなは元気ですか。', 'Mọi người trong nhà anh có khỏe không?', 5),
  (49, '～まして', 'Bạn có thể chuyển động từ V(thể て ) thành V(thể ます )+ まして khi bạn muốn câu văn lịch sự hơn. Trong câu văn dùng kính ngữ, ～まして thường được dùng để tạo sự thống nhất trong câu: 例1 ： Hải bị sốt, mẹ Hải gọi điện đến cho thầy giáo Hải :', 'ハイはゆうべ熱を出しまして、今朝もまだ下がらないんです。', 'Cháu Hải bị sốt từ tối qua, đến sáng nay vẫn chưa hạ sốt ạ.', 6),
  (49, 'Một số điều cần lưu ý', 'Khi bày tỏ sự kính trọng của mình đối với người nghe, ngoài việc sử dụng kính ngữ ra, bạn còn cần phải chú ý 2 điều sau đây:', 'コーヒーが飲みたいですか。（X）', 'Ông có muốn uống cà phê không?', 7),
  (50, '謙譲語 (けんじょうご) - Khiêm tốn ngữ', '謙譲語 ( けんじょうご ) là cách diễn đạt trong đó người nói thể hiện sự khiêm nhường khi nói về bản thân , cũng như hạ thấp những hành động của bản thân mình để bày tỏ sự kính trọng đối với người nghe hoặc người được đề cập đến trong câu chuyện ( tức là nhún mình xuống để nâng người đó lên). Cũng tương tự như 尊敬語 ( そんけいご ) mà ta đã học ở bài trước, 謙譲語 ( けんじょうご ) cũng được dùng để thể hiện sự kính trọng đối với người trên, hoặc người ngoài nhóm. Nó cũng được sử dụng khi người nói nói về người nào đó trong nhóm của mình( ウチの人 ) với người ngoài nhóm （ソトの人）', 'お/ご～します:', 'a. お V （ thể ます）します ( V : nhóm I, II)', 1),
  (50, 'Động từ khiêm tốn ngữ đặc biệt', 'Một số động từ có động từ khiêm tốn ngữ đặc biệt tương ứng. Xem bảng sau : Động từ gốc Động từ khiêm tốn ngữ', '社長の奥さんに会いました。', 'Tôi đã gặp vợ giám đốc.', 2),
  (50, '丁寧語(ていねいご) - Từ ngữ lịch sự', 'Từ ngữ lịch sự là cách diễn đạt biểu thị thái độ lịch sự, tôn trọng đối với người nghe. Điển hình của là câu văn ở thể lịch sự 「です・ます」 .', '明日東京へ参ります。（O）', 'Ngày mai tôi đi Tokyo.', 3)
) AS v(lesson_number, pattern, explanation_vi, example_ja, example_vi, ord)
JOIN mnn_lessons l ON l.site_id = '1219bda2-aa1e-4288-ab7e-caff011cdf5c'
                  AND l.lesson_number = v.lesson_number;

