  (27, 2, '私ははしが使えます。', 'わたしははしがつかえます。', 'Tôi có thể sử dụng đũa.', 12),
  (27, 2, 'この銀行でドルが換えられます。', 'このぎんこうでドルがかえられます。', 'Bạn có thể đổi Đôla ở ngân hàng này.', 13),
  (27, 2, 'こちらで料理教室が開けますか。', 'こちらでりょうりきょうしつがひらけますか。', 'Tôi có thể mở lớp nấu ăn ở đây được không?', 14),
  (27, 3, '新宿で今くろさわのえいがが見られます。', 'しんじゅくでいまくろさわのえいががみられます。', 'Bạn có thể xem phim của Kurosawa ở Shinjuku bây giờ.', 1),
  (27, 3, '電話で天気予報が聞けますよ。', 'でんわでてんきよほうがきけますよ。', 'Bạn có thể nghe dự báo thời tiết bằng điện thoại đấy.', 2),
  (27, 3, '隣の部屋からラジオの音が聞こえます。', 'となりのへやからラジオのおとがきこえます。', 'Tôi nghe thấy tiếng radio từ phòng bên cạnh.', 3),
  (27, 3, '新幹線から富士さんが見えます。', 'しんかんせんからふじさんがみえます。', 'Có thể nhìn thấy núi Phú Sĩ từ shinkansen.', 4),
  (27, 3, '暗いですから何も見えません。', 'くらいですからなにもみえません。', 'Vì trời tối nên tôi không nhìn thấy gì.', 5),
  (27, 3, '毎日忙しいですから、テレビが見られません。', 'まいにちいそがしいですから、テレビがみられません。', 'Vì hàng ngày bận nên tôi không thể xem tivi.', 6),
  (27, 3, '例：7静かですから、隣のうちの声が聞こえます。', '例：7しずかですから、となりのうちのこえがきこえます。', 'Vì yên tĩnh nên có thể nghe thấy âm thanh từ nhà bên cạnh.', 7),
  (27, 3, 'テープレコーダーがあったら、このテープが聞けます。', 'テープレコーダーがあったら、このテープがきけます。', 'Nếu có đài cát- sét thì có thể nghe được cuộn băng này.', 8),
  (27, 4, '駅の前に大きいスーパーができました？', 'えきのまえに大きいスーパーができました？', 'Ở trước ga có một siêu thị lớn vừa được hoàn thành.', 1),
  (27, 4, '時計の修理はいつできますか。', 'とけいのしゅうりはいつできますか。', 'Việc sửa chiếc đồng hồ này bao giờ thì xong? ( Bao giờ thì sửa xong cái đồng hồ này).', 2),
  (27, 5, '私が学校で英語を勉強しています。私は学校で英語を勉強しています。英語は学校で勉強しています。学校では英語を勉強しています。私の学校にはアメリカ人の先生がいます。', '私が学校で英語を勉強しています。私は学校で英語を勉強しています。英語は学校で勉強しています。学校では英語を勉強しています。わたしのがっこうにはアメリカ人の先生がいます。', 'Ở trường của tôi thì có giáo viên người Mỹ.', 1),
  (27, 5, '私の学校では中国語が習えます。', 'わたしのがっこうではちゅうごくごがならえます。', 'Ở trường tôi thì có thể học tiếng Trung Quốc.', 2),
  (27, 5, 'きのう山が見えました。今日見えません。', 'きのうやまがみえました。きょうみえません。', 'Hôm qua nhìn thấy được núi. Hôm nay không thấy.', 3),
  (27, 5, 'きのうは山が見えましたが、今日は見えません。', 'きのうはやまがみえましたが、きょうはみえません。', 'Hôm qua thì nhìn thấy được núi nhưng hôm nay thì không thấy.', 4),
  (27, 5, 'ワインを飲みます。ビールを飲みません。', 'ワインをのみます。ビールをのみません。', 'Tôi uống rượu vang. Tôi không uống bia.', 5),
  (27, 5, 'ワインは飲みますが、ビールは飲みません。', 'ワインはのみますが、ビールはのみません。', 'Rượu vang thì tối uống nhưng bia thì không uống.', 6),
  (27, 5, 'ひらがなが書けます。カタカナが書けません。', 'ひらがながかけます。カタカナがかけません。', 'Tôi có thể viết được chữ Hiragana. Tôi không viết được chữ Katakana.', 7),
  (27, 5, 'ひらがなは書けますが、カタカナは書けません。', 'ひらがなはかけますが、カタカナはかけません。', 'Chữ Hiragana thì tôi có thế viết được, còn chữ Katakana thì không.', 8),
  (27, 5, '京都きょうとへ行きます。大阪おおさかへ行きません。', '京都きょうとへいきます。大阪おおさかへいきません。', 'Tôi đi Kyoto. Tôi không đi Osaka.', 9),
  (27, 5, '京都きょうとへは行きますが、大阪おおさかへは行きません。', '京都きょうとへはいきますが、大阪おおさかへはいきません。', 'Kyoto thì tôi sẽ đi nhưng Osaka thì không.', 10),
  (27, 6, 'ハイさんは英語が話せます。フランス語も話せます。', 'ハイさんはえいごがはなせます。フランスごもはなせます。', 'Anh Hải có thể nói tiếng Anh. Anh ấy cũng nói được cả tiếng Pháp.', 1),
  (27, 6, '去年アメリカへ行きました。メキシコ[へ]も行きました。', 'きょねんアメリカへいきました。メキシコ[へ]もいきました。', 'Năm ngoái tôi đã đi Mỹ. Tôi cũng đi cả Mehico.', 2),
  (27, 6, '私のへやから海が見えます。弟の部屋からも見えます。', 'わたしのへやからうみがみえます。おとうとのへやからもみえます。', 'Từ phòng tôi có thể nhìn thấy được biển. Từ phòng em trai tôi cũng có thể thấy được.', 3),
  (27, 7, 'ローマ字しか書けません。', 'ローマ字しかかけません。', 'Tôi viết được mỗi chữ Romaji thôi.', 1),
  (27, 7, 'ローマ字だけ書けます。', 'ローマ字だけかけます。', 'Tôi chỉ viết được chữ Romaji.', 2),
  (27, 7, 'あの人の名前を思い出すことができませんか。', 'あのひとのなまえをおもいだすことができませんか。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 3),
  (27, 7, '明日１０時ごろ来ることができると思います。', 'あした１０じごろくることができるとおもいます。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 4),
  (27, 7, '一人で病院へ行くことができなかったんです。', 'ひとりでびょういんへいくことができなかったんです。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 5),
  (27, 7, '１０時までに帰ることができたら、電話をください。', '１０じまでにかえることができたら、でんわをください。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 6),
  (27, 7, 'タワポン(たわぽん)さんはパソコン(ぱそこん)を使うことができないことと言いました。', 'タワポン(たわぽん)さんはパソコン(ぱそこん)をつかうことができないことといいました。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 7),
  (27, 7, 'スポ(すぽ)ーツ(つ)が好きですか。（ゴルフ(ごるふ)…(…)O(Ｏ)ほかのスポツ…Ｘ）', 'スポ(すぽ)ーツ(つ)がすきですか。（ゴルフ(ごるふ)…(…)O(Ｏ)ほかのスポツ…Ｘ）', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 8),
  (27, 7, 'コ(こ)ーヒ(ひ)ーに砂糖とミルク(みるく)を入れますか。（ミルク(みるく)…(…)O(Ｏ)砂糖…(…)Ｘ）', 'コ(こ)ーヒ(ひ)ーにさとうとミルク(みるく)をいれますか。（ミルク(みるく)…(…)O(Ｏ)さとう…(…)Ｘ）', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 9),
  (27, 7, '会社やうちでパソコン(ぱそこん)を使っていますか。', 'かいしゃやうちでパソコン(ぱそこん)をつかっていますか。', '… ＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿', 10),
  (28, 1, '音楽を聞食事します。', 'おんがくをききながらしょくじします。', 'Tôi vừa nghe nhạc vừa ăn cơm.', 1),
  (28, 1, '働きながら日本語を勉強しています。', 'はたらきながらにほんごをべんきょうしています。', 'Tôi đang vừa đi làm vừa học tiếng Nhật.', 2),
  (28, 1, 'お茶を飲みながら話しませんか。', 'おちゃをのみながらはなしませんか。', 'Chúng ta vừa uống trà vừa nói chuyện nhé.', 3),
  (28, 2, '毎朝ジョギングをしています。', 'まいあさジョギングをしています。', 'Tôi chạy bộ mỗi sáng.', 1),
  (28, 2, '暇な時、いつも音楽を聞いています。', 'ひまなとき、いつもおんがくをきいています。', 'Khi rảnh rỗi, lúc nào tôi cũng nghe nhạc.', 2),
  (28, 2, '子供の時、毎晩8時に寝ていました。', 'こどものとき、まいばん8じにねていました。', 'Hồi bé, mỗi tối tôi thường đi ngủ vào lúc 8 giờ.', 3),
  (28, 2, '体が弱いですから、毎日薬を飲んでいます。', '体が弱いですから、毎日薬を飲んでいます。', 'Vì tôi yếu nên tôi uống thuốc hàng ngày.', 4),
  (28, 3, 'ワット先生は熱心だし、まじめだし、経験もあります。', 'ワット先生はねっしんだし、まじめだし、けいけんもあります。', 'Thầy Watt vừa nhiệt tình, lại chăm chỉ và có kinh nghiệm.', 1),
  (28, 3, '駅から遠いし、近くに店がないし、ここは不便です。', 'えきからとおいし、ちかくにみせがないし、ここはふべんです。', '(Các mệnh đề đều đề cập đến điểm không tốt của chỗ này )', 2),
  (28, 3, '今年の夏は海に行って、山にも行った。', 'ことしのなつはうみにいって、やまにもいった。', 'Hè năm nay thì tôi đi biển, và cũng đi cả núi nữa.', 3),
  (28, 3, '今年ことしの夏は海に行ったし、山にも行った。(＝たくさんいきました)', '今年ことしのなつはうみにいったし、やまにもいった。(＝たくさんいきました)', 'Hè năm năm thì tôi không những đi biển mà còn đi cả núi nữa.( hàm ý tôi đã đi rất nhiều nơi)', 4),
  (28, 3, '荷物も多いし、雨も降っているし、タクシーで帰ります。', 'にもつもおおいし、あめもふっているし、タクシーでかえります。', 'Hành lý nhiều, trời lại mưa nên tôi sẽ về bằng taxi .', 5),
  (28, 3, '息子に英語を教えていただけませんかた。', 'むすこにえいごをおしえていただけませんかた。', 'Anh có thể dạy tiếng Anh cho con trai tôi được không?', 6),
  (28, 3, 'うーん、出張も多いし、もうすぐ日本語の試験もあるし….', 'うーん、しゅっちょうもおおいし、もうすぐにほんごのしけんもあるし….', 'Nhưng tôi phải đi công tác nhiều, mà lại sắp thi tiếng Nhật rồi nữa,...', 7),
  (28, 3, '色もきれいだし、この靴を買います。', 'いろもきれいだし、このくつをかいます。', 'Tôi mua đôi giày này vì màu của nó đẹp ( và còn một số lý do khác nữa, ví dụ như : kiểu dáng, chất liệu, giá cả,…).', 8),
  (28, 3, '色がきれいだから、この靴を買います。', 'いろがきれいだから、このくつをかいます。', 'Tôi mua đôi giày này vì màu đẹp. ( chỉ có mỗi một lý do này )', 9),
  (28, 4, 'どうして名古屋大学を選んだんですか。', 'どうしてなごやだいがくをえらんだんですか。', 'Tại sao bạn lại chọn trường đại học Nagoya.', 1),
  (28, 4, '名古屋大学は父が出た大学だし、いい先生も多いし、それに家かいですから。', 'なごやだいがくはちちがでた大学だし、いい先生もおおいし、それにいえからかいですから。', 'Vì trường ĐH Nagoya là trường bố tôi đã tốt nghiệp, có nhiều thầy tốt, hơn nữa lại gần nhà.', 2),
  (28, 5, 'このレストランは値段も安いし、おいしいんです。', 'このレストランは値段も安いし、おいしいんです。', 'Nhà hàng này v ừa rẻ lại vừa ngon.', 1),
  (28, 5, 'それで人が多いんですね。', 'それで人が多いんですね。', 'Thế nên mới đông nhỉ.', 2),
  (29, 1, 'NがVています:窓が割れています。', 'NがVています:まどがわれています。', 'Cửa sổ bị vỡ.', 1),
  (29, 1, '電気がついています。', 'でんきがついています。', 'Đèn sáng.', 2),
  (29, 1, '昨日部屋に帰ったら電気がついていました。', 'きのうへやにかえったらでんきがついていました。', 'Hôm qua khi tôi về phòng thì thấy điện sáng.', 3),
  (29, 1, 'この椅子は壊れています。', 'このいすはこわれています。', 'Chiếc ghế này bị hỏng.', 4),
  (29, 2, 'ハイさんが持って来たワインは全部飲んでしまいました。', 'ハイさんがもってきたワインはぜんぶのんでしまいました。', 'Tôi đã uống hết tất cả số rượu mà anh Hải đem tới rồi.', 1),
  (29, 2, '漢字の宿題はもうやってしまいました。', 'かんじのしゅくだいはもうやってしまいました。', 'Bài tập chữ Hán thì tôi đã làm hết rồi.', 2),
  (29, 2, '昼ごはんまでにレポートを書いてしまいます。', 'ひるごはんまでにレポートをかいてしまいます。', 'Tôi sẽ viết xong bản báo cáo trước bữa trưa.', 3),
  (29, 3, 'パスポートをなくしてしまいました。', 'パスポートをなくしてしまいました。', 'Tôi làm mất hộ chiếu mất rồi.', 1),
  (29, 3, 'パソコンが故障してしまいました。', 'パソコンがこしょうしてしまいました。', 'Máy tính bị hỏng mất rồi.', 2),
  (29, 4, '前にはここにフォーの店がありました。', 'まえにはここにフォーのみせがありました。', 'Trước kia ở đây có một cửa hàng phở.', 1),
  (29, 4, '何を探していますか。', 'なにをさがしていますか。', 'Bạn đang tìm gì thế?', 2),
  (29, 4, 'かばんを探しています。あ、ありました。', 'かばんをさがしています。あ、ありました。', 'Tôi đang tìm chiế cặp. A, đây rồi ( tôi thấy rồi).', 3),
  (29, 5, 'どこかで財布をなくしてしまいました。', 'どこかでさいふをなくしてしまいました。', 'Tôi đã làm mất tiêu chiếc ví ở đâu đó rồi.', 1),
  (29, 5, 'どこかに電話がありませんか。', 'どこかにでんわがありませんか。', 'Có cái điện thoại nào ở đâu đây không?', 2),
  (30, 1, 'N1にN2がVてあります：ハイさんの本には、みんなハイさんの名前が書いてあります。', 'N1にN2がVてあります：ハイさんの本には、みんなハイさんのなまえがかいてあります。', 'Trên tất cả các quyển sách của anh Hải đều ghi tên của anh ấy.', 1),
  (30, 1, '壁に私が好きな歌手の写真が貼ってあります。', 'かべにわたしがすきな歌手のしゃしんがはってあります。', 'Trên tường có dán ảnh ca sĩ mà tôi yêu thích.', 2),
  (30, 1, 'カレンダーに今月の予定が書いてあります。', 'カレンダーにこんげつのよていがかいてあります。', 'Trên lịch có ghi những dự định của tháng này.', 3),
  (30, 1, '私が好きな歌手の写真は壁に貼ってあります。', '私が好きな歌手の写真は壁に貼ってあります。', 'Ảnh của ca sĩ mà tôi thích thì được dán ở trên tường.', 4),
  (30, 1, 'ホテルはもう予約してあります。', 'ホテルはもうよやくしてあります。', 'Khách sạn thì tôi đã đặt rồi.', 5),
  (30, 2, '山田君、紙がないから、買っておいてください。', 'やまだくん、かみがないから、かっておいてください。', 'Yamada, hết giấy rồi nên cậu mua sẵn đi nhé.( mua giấy để chuẩn bị trước khi nào cần dùng là sẽ có giấy luôn)', 1),
  (30, 2, 'はい、わかりました。', 'はい、わかりました。', 'Vâng ạ.', 2),
  (30, 2, '次の会議までにこの資料を読んでおいてください。', 'つぎのかいぎまでにこのしりょうをよんでおいてください。', 'Hãy đọc tài liệu này trước buổi họp lần tới. ( để chuẩn bị cho buổi họp)', 3),
  (30, 2, '旅行の前に切符を買っておきます。', 'りょこうのまえにきっぷをかっておきます。', 'Tôi sẽ mua sẵn vé trước khi đi du lịch. ( Để đề phòng hết vé,..)', 4),
  (30, 2, 'はさみを使ったら、元の所に戻しておいてください。', 'はさみをつかったら、もとのところにもどしておいてください。', 'Dùng kéo xong thì cất lại chỗ cũ nhé. ( Để lần sau dùng không phải đi tìm)', 5),
  (30, 2, '窓を閉めましょうか。', 'まどをしめましょうか。', 'Tôi đóng cửa sổ nhé.', 6),
  (30, 2, 'いいえ、開けておいてください。まだ、この部屋を使いますから。', 'いいえ、あけておいてください。まだ、このへやをつかいますから。', 'Không, cứ để mở thế. Vì tôi vẫn còn dùng phòng này mà.', 7),
  (30, 2, '机を片づけましょうか。', '机を片づけましょうか。', 'Tôi dọn bàn nhé.', 8),
  (30, 2, 'いいえ、そのままにしておいてください。', 'いいえ、そのままにしておいてください。', 'Không, cứ để nguyên đấy.', 9),
  (30, 2, 'そこに置おいといてください。', 'そこに置おいといてください。', 'Hãy đặt nó ở đó.', 10),
  (30, 2, '週末までにこの本を読んでおきます。(O)', 'しゅうまつまでにこの本をよんでおきます。(O)', 'Tôi sẽ đọc trước quyển sách này trước cuối tuần.', 11),
