JOIN mnn_lessons l ON l.site_id = '1219bda2-aa1e-4288-ab7e-caff011cdf5c'
                  AND l.lesson_number = s.lesson_number
JOIN mnn_grammar g ON g.lesson_id = l.id
                  AND g.order_index = s.g_ord;

-- Đặt lại NOT NULL cho mnn_sentences sau khi seed (xem chú thích công cụ).
ALTER TABLE mnn_sentences ALTER COLUMN lesson_id SET NOT NULL;
ALTER TABLE mnn_sentences ALTER COLUMN ja_kanji SET NOT NULL;
ALTER TABLE mnn_sentences ALTER COLUMN ja_kana SET NOT NULL;
ALTER TABLE mnn_sentences ALTER COLUMN vi SET NOT NULL;
ALTER TABLE mnn_sentences ALTER COLUMN has_furigana SET NOT NULL;
